window.PALACE = {"title": "The Wending House", "start": 0, "latitude": 44.26, "longitude": -88.41, "facing": 180, "help": "<p>This is a memory palace for my instruments, games, drafts, and books. Every room keeps something. You can also skip the walking and use the Catalogue.</p>", "wings": {"foyer": {"name": "The Foyer", "color": "#8C3F2F"}, "instruments": {"name": "The Instrument Gallery", "color": "#B07A1E"}, "turnings": {"name": "The Turnings", "color": "#B5452B"}, "numbers": {"name": "The Numbers, below", "color": "#2F5E9E"}, "pond": {"name": "The Lily Pond", "color": "#3C7A54"}, "schoolroom": {"name": "The Schoolroom", "color": "#3C7A54"}, "workshop": {"name": "The Workshop", "color": "#7A4A86"}, "lectures": {"name": "The Lecture Wing", "color": "#2C7B80"}, "branch": {"name": "The Branch Cut", "color": "#3A6E8F"}, "court": {"name": "The Courtyards", "color": "#A3803F"}, "garden": {"name": "The Gardens", "color": "#5E7A3A"}, "archive": {"name": "The Archive", "color": "#5E4A6E"}, "hall": {"name": "The Great Hall", "color": "#4F6A5A"}, "tower": {"name": "The Tower", "color": "#5A6A82"}}, "ranks": [{"name": "Visitor", "xp": 0, "color": "#D9D2C0"}, {"name": "Reader", "xp": 60, "color": "#7A9E7E", "gift": "The reading room's lamps burn a little brighter for you."}, {"name": "Third Assistant Librarian", "xp": 160, "color": "#B8322A", "gift": "You may borrow keys from the porter."}, {"name": "Second Assistant Librarian", "xp": 320, "color": "#E0B42F", "gift": "The closed stacks under the spiral are open to you."}, {"name": "Keeper of the Stacks", "xp": 600, "color": "#2F4E8C", "gift": "Every lamp is yours."}], "sheets": {"log": {"name": "the log stair", "sym": "landing"}, "sqrt": {"name": "the branch cut", "sym": "√", "mod": 2}}, "warps": {"ENTRY": {"room": 0}, "LAME": {"room": 16, "say": "The corridor narrows around you."}, "BABEL": {"room": 18}, "FUNES": {"room": 15}, "DOZEN": {"room": 17}, "KNAVE": {"room": 27}, "BRANCH": {"room": 30}, "SUNDIAL": {"room": 34}, "SHEET": {"room": 29, "say": "You come out between two shelves that aren't on any plan."}}, "links": [{"title": "Home", "href": "/", "note": "the front page"}, {"title": "About", "href": "/about/"}, {"title": "Teaching", "href": "/teaching/"}, {"title": "Projects", "href": "/projects/"}, {"title": "Collections", "href": "/collections/"}, {"title": "Code", "href": "/code/"}, {"title": "Puzzles & Devices", "href": "/puzzles/", "note": "every device, as a plain list"}, {"title": "Contact", "href": "/contact/"}], "items": {"golden-key": "a golden key, stamped φ", "hourglass": "an hourglass", "primer": "A Young Lady's Illustrated Primer", "astrolabe": "an astrolabe with a storm glass", "musicbox": "a music box"}, "catalog": {"url": "/catalog/index.json"}, "dials": {"horizontal": {"name": "The horizontal dial", "blurb": "A brass plate and a style aimed at the pole: the sun's own time, as it falls here.", "notes": ["The style (the shadow-casting edge) is tilted to the latitude so that it lies parallel to the earth's axis. That one choice makes every hour the same length all year: the sun turns about the style at 15° an hour, whatever its height.", "On a horizontal plate the hour lines are not evenly spaced. Each makes an angle θ with the noon line where tan θ = sin φ · tan(15° × hours from noon), φ being the latitude. At the pole the lines would be even; at the equator they would all crowd toward six o'clock.", "The oldest surviving dial with a style parallel to the earth's axis was made by the astronomer Ibn al-Shatir in 1371–72 for the Umayyad Mosque in Damascus, on a marble slab about two meters by one. The original is in the Damascus museum; a copy stands on the minaret. European dials took up the polar style in the fifteenth century.", "The dial reads apparent solar time, the sun's own time here. It differs from a clock by the longitude within the time zone, by daylight saving, and by the equation of time."], "sources": ["Ibn al-Shatir, in Thomas Hockey and others, eds., <i>Biographical Encyclopedia of Astronomers</i>.", "René R. J. Rohr, <i>Sundials: History, Theory, and Practice</i>, 1970.", "Albert E. Waugh, <i>Sundials: Their Theory and Construction</i>, 1973."]}, "armillary": {"name": "The armillary sphere", "blurb": "An equatorial dial: the polar rod's shadow on an evenly divided band.", "notes": ["An armillary sphere is the sky reduced to its circles: rings (armillae) for the horizon, the meridian, the equator, and often the ecliptic, nested around a center that stands for the earth. The idea is old: a ringed model of the celestial sphere was in common use from the time of Eratosthenes, in the third century BC.", "Observing armillaries were real instruments, not ornaments. Ptolemy describes one in the Almagest; astronomers at Maragha and Samarkand used them; Tycho Brahe built several in the 1580s. In China, Zhang Heng's armillary sphere of the second century was turned by water, and Su Song's clock tower of 1092 carried a water-driven armillary on its roof.", "As a sundial, the armillary is the simplest of all. A rod parallel to the earth's axis throws its shadow on a band lying in the plane of the equator, and because the band is perpendicular to the rod, the hours on it are exactly evenly spaced: 15° each.", "Twice a year, at the equinoxes, the sun lies in the plane of the equator, and the band shades its own inner face. On those days the rod's shadow vanishes into the band's edge."], "sources": ["Museo della Specola, Università di Bologna, <i>Armillary spheres</i>.", "Whipple Museum of the History of Science, Cambridge, <i>The observational armillary sphere</i>.", "Joseph Needham, <i>Heavenly Clockwork</i>, 1960."]}, "meantime": {"name": "The mean-time dial", "blurb": "A plate of figure-eights. The shadow of a bead on a pin tells the clock's own time, with the equation of time and the longitude already worked in.", "notes": ["A sundial tells the sun's time; a clock tells mean time, which runs evenly. The difference is the equation of time. The sun is up to about 16½ minutes fast in early November and 14¼ minutes slow in mid-February, and the two agree near 15 April, 13 June, 1 September, and 25 December.", "It has two causes, which add: the earth moves faster near perihelion in early January (a yearly swing of about 7½ minutes), and the sun's path is tilted 23.4° to the equator (a half-yearly swing of about 10 minutes). Huygens published the first essentially correct tables in 1665, and Flamsteed in 1672–73.", "This dial does the correction for you. Instead of straight hour lines it carries a figure-eight (an analemma) for each clock hour: where the bead's shadow falls at that standard time on each day of the year. The house computes them from the sun's real position for wherever the house stands, so the shadow reads standard time directly. Read the left or right loop according to the season.", "In 1906 the firm of Pilkington and Gibbs in Preston, England, began making the heliochronometer, which builds the same correction into a shaped gnomon and a sliding scale. They stood at railway stations and public buildings, and were said to keep time to about thirty seconds."], "sources": ["Wikipedia, <i>Equation of time</i>.", "North American Sundial Society, the Sundial Registry: Pilkington & Gibbs heliochronometers.", "Jean Meeus, <i>Astronomical Algorithms</i>, 1991."]}, "meridiana": {"name": "The glass sphere", "blurb": "A glass ball on a column throws a spot of sun on the paving; at clock noon it crosses the figure-eight, at sun noon the straight line.", "notes": ["This is a meridiana: a noon mark laid along the north–south line, crossed by a spot of sunlight at the moment of local noon. The great ones were built inside churches, where a small hole high in the roof throws an image of the sun onto a brass line in the floor.", "In Bologna, Gian Domenico Cassini laid a meridian across the basilica of San Petronio in 1655. The hole is 27.07 meters above the floor, exactly 1000 Paris inches, and is one-thousandth of that height across. With it Cassini timed the equinoxes and measured the changing size of the sun's image, which gave evidence for Kepler's account of the earth's orbit: the sun's distance changes through the year, and the earth moves faster when it is closer.", "In Paris, the gnomon of Saint-Sulpice was begun by the clockmaker Henry Sully in 1727 and completed by Pierre Charles Le Monnier, who added the marble obelisk in 1743. It was built to fix the date of the spring equinox, and so of Easter; Le Monnier also used it to watch the tilt of the earth's axis change. (It is not the pagan relic of <i>The Da Vinci Code</i>.)", "Here a glass ball does the work of the hole. The month marks show where the spot falls at sun noon on the first of each month, high in summer and long in winter; the red figure-eight shows where it falls at clock noon, so the gap between them is the equation of time and the longitude, drawn on the stone."], "sources": ["Basilica di San Petronio, <i>La meridiana</i>.", "J. L. Heilbron, <i>The Sun in the Church: Cathedrals as Solar Observatories</i>, 1999.", "Wikipedia, <i>Gnomon of Saint-Sulpice</i>."]}, "cannon": {"name": "The noon cannon", "blurb": "A burning glass over the touch-hole: when the sun crosses the meridian on a clear day, it fires.", "notes": ["In 1786 a watchmaker named Rousseau, who kept a shop in the Galerie de Beaujolais, set a small cannon in the garden of the Palais-Royal in Paris with a lens above it. At the sun's noon the lens focused the light on the powder, and the gun fired, loud enough to be heard most of a kilometer away. Parisians set their watches by it; the phrase <i>midi pétant</i>, noon on the dot, is said to come from it.", "It fired on every sunny day until 1911, when France changed from Paris time to Greenwich time and noon by the sun stopped being noon by the clock. Its lens was stolen in 1998, and it is now fired by hand on a few days a year.", "A noon gun is a meridian instrument that keeps no record: it tells you only that the sun has just crossed the meridian, and only if the sky is clear. The house's cannon fires the same way, at local apparent noon, and only for those standing in the court."], "sources": ["Sortir à Paris, <i>The small cannon of the Palais-Royal</i>.", "Atlas Obscura, <i>Small Cannon of the Palais Royal</i>."]}}, "renovation": {"note": "Closed for renovation. The house is being rebuilt a few rooms at a time; this one will open again when it's ready. — W. K."}, "letter": "Visitor,\n\nYou have come in by the front door, which is the only one that is always open. This house is mostly a library: of instruments and games, of books that exist and books that don't yet, and of a few rooms that only make sense at night.\n\nThe rooms keep real time. The sun comes in where the sun actually is, and the weather in the windows is the weather in Appleton. Some doors keep hours. Some loops don't bring you back where you started.\n\nOn the desk: a ring of keys and the full plan, if you'd like every door open; a folded map and a compass, if you'd rather find your way; or leave everything where it is and walk in with nothing. You can always come back and change your mind.\n\nMost of the house is closed while I rebuild it. The office is open, and there is a linking book in it that will take you to the archive.\n\nThe board on the right goes everywhere directly. The board on the left has this week's problem. Out the left-hand door is a court with a sundial and the open sky; there is an astrolabe hanging there, if you want the sky over somewhere else.\n\nW. K.\n\nP.S. To wend is to turn, or to go one's way. Here it means both.\n", "news": [{"date": "2026-10-03", "text": "Most of the house is closed for renovation. The Entry, the Office, the Sundial Court, and the Archive are open, and the Archive's log book is the new catalogue.", "href": "#22"}, {"date": "2026-10-02", "text": "The palace has a name: the Wending House. Also: gardens, a carriage clock, and the planets tracked.", "href": "#0"}, {"date": "2026-10-01", "text": "The Entry gets a notice board, a link board, and an almanac.", "href": "#0"}, {"date": "2026-10-01", "text": "The engraved view: rooms in three dimensions, lit by the real sun.", "href": "#1"}, {"date": "2026-10-01", "text": "Lily Pads: sticky growth in a pond.", "href": "/lily-pads/"}, {"date": "2026-09-30", "text": "The Wending House opens.", "href": "#0"}], "events": [], "office": {"where": "", "unset": "Office hours for the term will be posted here."}, "office_hours": [], "puzzles": [{"q": "A bat and a ball cost $1.10 together. The bat costs $1.00 more than the ball. What does the ball cost?", "a": "Five cents. (Not ten: then the bat would cost $1.10 and the pair $1.20.)", "source": "a classic"}, {"q": "Remove two opposite corners from a chessboard. Can the remaining 62 squares be tiled by 31 dominoes?", "a": "No. Opposite corners have the same color, so 32 squares of one color remain and 30 of the other, but each domino covers one of each.", "source": "a classic"}, {"q": "A hundred lockers stand closed. Student k toggles every k-th locker, for k = 1 to 100. Which lockers end up open?", "a": "The perfect squares, 1, 4, 9, …, 100: ten lockers. A locker is toggled once per divisor, and only squares have an odd number of divisors.", "source": "a classic"}, {"q": "How many zeros does 100! end in?", "a": "24: there are 20 multiples of 5 up to 100, and 4 multiples of 25 contribute one more 5 each.", "source": "a classic"}, {"q": "What is the last digit of 7<sup>2026</sup>?", "a": "9. The last digits of powers of 7 cycle 7, 9, 3, 1, and 2026 leaves remainder 2 when divided by 4.", "source": "a classic"}, {"q": "In how many ways can a 2 × 10 strip be tiled by 1 × 2 dominoes?", "a": "89, a Fibonacci number: a tiling of a 2 × n strip ends either in one upright domino or in two flat ones, so the counts satisfy the Fibonacci recurrence.", "source": "a classic"}, {"q": "Which positive integers can be written as a sum of two or more consecutive positive integers?", "a": "Exactly those that are not powers of 2.", "source": "after Richard Guy"}, {"q": "How many squares, of all sizes, are there on a chessboard?", "a": "204 = 1² + 2² + … + 8².", "source": "a classic"}, {"q": "Below 100, which pair of numbers makes Euclid's algorithm take the most steps?", "a": "89 and 55, consecutive Fibonacci numbers, which take 9 steps. (See Lamé's Corridor.)", "source": "after Lamé, 1844"}, {"q": "On the island of knights and knaves, A says: “We are both knaves.” What are A and B?", "a": "A is a knave and B is a knight. A knight could never say it, so A lies, and the statement is false, so not both are knaves.", "source": "in the manner of Smullyan"}, {"q": "On the same island, A says: “At least one of us is a knave.” What are A and B?", "a": "A is a knight and B is a knave. If A were a knave, the statement would be true, which is impossible; so A tells the truth, and B must be the knave.", "source": "in the manner of Smullyan"}, {"q": "Ten people meet, and each shakes hands once with each of the others. How many handshakes are there?", "a": "45 = 10 · 9 / 2.", "source": "a classic"}, {"q": "What is the sum of the first 100 odd numbers?", "a": "10,000. The first n odd numbers always sum to n², as an L-shaped layer added to a square.", "source": "a classic"}], "rooms": [{"id": 1, "closed": "renovation", "name": "The Hexagonal Reading Room", "wing": "foyer", "shape": "hex", "floor": "checker", "ceiling": "coffers", "decor": ["shelves", "lamp", "rug", "window"], "at": [5, 5], "text": "Six walls, four of them doors. Every reading room should be a hexagon. The lamp comes on at dusk, whether or not anyone is reading.\nOn the lectern lies the plan of a book that isn't written yet. The card catalogue in the corner knows where everything is. It is the honest way through, and the walking is the other way.", "again": "The rug has worn a little where you keep crossing it.", "phases": [{"when": "hours:0-1", "text": "It is past midnight. A door that isn't there by day stands open behind you.", "doors": [{"to": 23, "wall": "front", "oneway": true, "title": "the midnight door"}]}, {"when": "dawn", "text": "Dawn. The first reader of the day is always the dust."}], "marginalia": ["Hexagons tile the plane, which is why Borges could build his library of them. They do not tile space; his galleries stack in floors joined by spiral stairs.", "The memory palace is the oldest technique on this site: put each thing to be remembered in a room, then walk the rooms."], "sources": ["The hexagonal galleries of Borges's “The Library of Babel.”", "The method of loci, credited by Cicero to the poet Simonides of Ceos, who could name the guests at a collapsed banquet hall by remembering where each had sat."], "bib": ["Jorge Luis Borges, “La biblioteca de Babel,” 1941; in <i>Ficciones</i>, 1944.", "Cicero, <i>De Oratore</i>, Book II.", "Frances A. Yates, <i>The Art of Memory</i>, 1966."], "doors": [{"to": 2, "wall": "right", "title": "brass and glass"}, {"to": 8, "wall": "left", "title": "a draft that turns"}, {"to": 13, "wall": "back", "turn": "r", "title": "a stair going down", "say": "The stair winds a quarter turn as it descends."}, {"to": 0, "wall": "front", "title": "out to the Entry"}], "objects": [{"kind": "unwritten", "icon": "lectern", "title": "Lie Groups You Can Hold", "note": "The book plan: slide rules as exponential maps, turned and pressed into SO(3), G₂, and their cousins. Drafts are in the Workshop."}, {"kind": "device", "icon": "books", "title": "The card catalogue", "action": "catalogue", "note": "Everything here, listed plainly."}, {"kind": "device", "icon": "map", "title": "A map, mostly blank", "action": "map", "note": "It fills in as you walk."}]}, {"id": 2, "closed": "renovation", "name": "The Gallery of Rules", "wing": "instruments", "decor": ["cases", "lamp"], "at": [6, 4], "text": "Long cases line the walls, and every one holds a rule: straight, circular, complex, finite-field, relativistic. A slide rule is the exponential map you can hold. Sliding adds logarithms, and reading multiplies numbers.\nOne case is empty. Its card says <i>Instruments Cabinet: sectors, Napier's bones, Gunter's scale, sextants. In preparation.</i>", "marginalia": ["A slide rule is the exponential map of the multiplicative group of positive reals: lengths add in the Lie algebra, numbers multiply in the group."], "sources": ["Napier's logarithms (1614), Gunter's logarithmic scale (1620), and Oughtred's circular slide rule (about 1630)."], "bib": ["Florian Cajori, <i>A History of the Logarithmic Slide Rule and Allied Instruments</i>, 1909.", "Peter M. Hopp, <i>Slide Rules: Their History, Models and Makers</i>, 1999."], "doors": [{"to": 1, "wall": "left"}, {"to": 3, "wall": "back"}, {"to": 4, "wall": "right", "title": "a narrow stair up"}], "objects": [{"kind": "key", "item": "plan", "icon": "map", "title": "A folded plan of the house", "when": "mode:hardcore"}, {"kind": "device", "icon": "rule", "title": "Slide Rule Cabinet", "href": "/slide-rules/", "note": "Straight, circular, complex, finite-field, and relativistic rules to drag and read."}, {"kind": "unwritten", "icon": "rule", "title": "The Instruments Cabinet", "note": "Sectors, Napier's bones and their descendants, log and trig tables, Gunter's scale, ruler constructions, scraping and flattening, inclinometers, and sextants."}, {"kind": "unwritten", "icon": "rule", "title": "Elliptic slide rule", "note": "A rule built on the ℘ function, using transparencies."}]}, {"id": 3, "closed": "renovation", "name": "The Bench", "wing": "instruments", "decor": ["bench", "lamp", "window"], "at": [7, 3], "text": "A drafting bench with four instruments that measure area by walking around it. The polar planimeter turns its wheel, the Prytz hatchet drags a blade, and the x–y encoder counts. Each has its own way of being wrong.", "marginalia": ["Every planimeter here is Green's theorem with a different mechanism for the integrand."], "sources": ["Jakob Amsler's polar planimeter (1854) and Holger Prytz's hatchet planimeter (1880s)."], "bib": ["Ronald W. Gatterdam, “The planimeter as an example of Green's theorem,” <i>American Mathematical Monthly</i> 88 (1981).", "Robert L. Foote, “Geometry of the Prytz planimeter,” <i>Reports on Mathematical Physics</i> 42 (1998)."], "doors": [{"to": 2, "wall": "left"}, {"to": 5, "wall": "right"}], "objects": [{"kind": "device", "icon": "planimeter", "title": "Planimeter Bench", "href": "/planimeters/", "note": "Polar, linear, hatchet, and x–y planimeters, with a running error budget."}]}, {"id": 4, "closed": "renovation", "name": "The Observatory", "wing": "instruments", "shape": "round", "decor": ["sky", "window"], "at": [6, 2], "text": "A small dome, and its ceiling is the sky over Appleton right now: the actual stars, the moon in its actual phase, and whichever planets are up. It repaints itself by the minute. By day it fades to the sun and the brightest stars. The chart is stereographic, like the Wulff net on the table, so circles in the sky stay circles on the ceiling.\nThe dome turns with you. If a corridor has turned you, north is no longer at the top. Come in mirrored and the whole sky is reversed, the way the ceiling of Grand Central Terminal was painted.", "mirror": "You are seeing the sky the way a god outside it would. The constellations run backwards.", "widget": "sky", "notes": [{"when": "night", "text": "The dome is open. A trapdoor has appeared behind you, and the pendulum hall shows through it."}, {"when": "moon:full", "text": "Full moon. Even the net's grid lines cast shadows."}], "marginalia": ["The dome is computed, not painted. Stars come from the Yale Bright Star Catalogue by way of d3-celestial, and the planets from JPL's approximate orbital elements. The sun and moon use low-precision formulas, good to about a degree.", "Stereographic projection sends circles to circles and keeps angles. It is the projection of the Wulff net, of the astrolabe, and of the Riemann sphere."], "sources": ["George Wulff's net (1902), the stereographic planisphere of Ptolemy's <i>Planisphaerium</i>, and the astrolabe.", "The ceiling of Grand Central Terminal (1913), whose zodiac runs backwards: it shows the sky from outside."], "bib": ["Tristan Needham, <i>Visual Complex Analysis</i>, 1997, ch. 3.", "Olaf Frohn, d3-celestial (software and data), BSD license."], "doors": [{"to": 2, "wall": "left"}, {"to": 7, "wall": "front", "when": "night|dusk", "title": "a trapdoor, open after dark"}], "objects": [{"kind": "device", "icon": "net", "title": "Stereonet Slide Rule", "href": "/stereonet/", "note": "The SO(3) slide rule: a Wulff net with a turning overlay and a frame-matching challenge."}, {"kind": "device", "icon": "orrery", "title": "The planet book", "action": "planets", "note": "Every planet tracked: where it is now, rising and setting, brightness, distance, and constellation."}]}, {"id": 5, "closed": "renovation", "name": "The Perspective Corridor", "shape": "corridor", "wing": "instruments", "decor": ["lamp"], "at": [8, 3], "text": "The corridor is longer than it looks, or shorter. The floorboards are evenly spaced, and that is the only thing you can trust. Four points on a line keep their cross-ratio under any picture of them.", "marginalia": ["The floorboards in this picture are equally spaced in depth, so in the picture each gap is the one before it scaled by a fixed rule (y = k/z). The cross-ratio of any four boards is the same in the room and in the picture."], "sources": ["Alberti's construction of the perspective floor, and Desargues's projective geometry."], "bib": ["Leon Battista Alberti, <i>De pictura</i>, 1435.", "H. S. M. Coxeter, <i>Projective Geometry</i>, 2nd ed., 1974."], "doors": [{"to": 3, "wall": "left"}, {"to": 6, "wall": "back"}, {"to": 33, "wall": "right", "title": "the arcades"}], "objects": [{"kind": "device", "icon": "cross", "title": "Cross-Ratio Ruler", "href": "/cross-ratio/", "note": "Read true distances off a perspective picture."}]}, {"id": 6, "closed": "renovation", "name": "The Hothouse", "wing": "instruments", "decor": ["glasshouse", "window"], "at": [8, 5], "text": "It's warm, and the arithmetic has gone tropical. As the base of the logarithm grows, addition melts into max and multiplication into plus. The plants don't mind.", "phases": [{"when": "night", "text": "After dark the night-blooming cereus opens. It has the largest flower in the room and the shortest season: one night."}, {"when": "sun:up", "text": "The panes fog in the sun, and the tropical rule's scale sweats."}], "marginalia": ["Tropical arithmetic is the limit of ordinary arithmetic on logarithms as the base goes to infinity: log_t(t^a + t^b) → max(a, b). Physicists call it Maslov dequantization."], "sources": ["The word “tropical” honors the Brazilian mathematician Imre Simon."], "bib": ["Diane Maclagan and Bernd Sturmfels, <i>Introduction to Tropical Geometry</i>, AMS, 2015."], "doors": [{"to": 5, "wall": "left"}, {"to": 20, "wall": "right", "title": "a door that smells of chalk"}], "objects": [{"kind": "device", "icon": "plant", "title": "Tropical Slide Rule", "href": "/tropical/", "note": "Watch addition turn into max."}]}, {"id": 7, "closed": "renovation", "name": "The Pendulum Hall", "wing": "instruments", "decor": ["pendulum", "lamp"], "at": [5, 2], "text": "A long wire from the ceiling, a brass bob, and a ring of pegs on the floor. The plane of the swing turns, slowly, clockwise. Nothing pushes it. The floor is turning underneath, and the pendulum is the one thing in the building that isn't.\nAt latitude φ the plane comes around by 360° · sin φ in a sidereal day. Equivalently, carrying a vector once around the circle of latitude, keeping it as straight as the sphere allows, brings it back turned by the area of the cap above you, 2π(1 − sin φ). That turn is holonomy, and this hall has some of its own: one of its doors is a mirror.", "mirror": "In the mirror, the pendulum still turns clockwise. Of everything here, it is the one thing that doesn't care which way you are facing.", "widget": "pendulum", "marginalia": ["The swing plane turns 360° · sin φ per sidereal day relative to the floor. Parallel transport around the circle of latitude gives the same thing as a holonomy: 2π(1 − sin φ), the area of the cap above the circle, which is −2π sin φ mod 2π."], "sources": ["Léon Foucault's pendulum, shown in Paris in 1851, at the Observatoire and then under the dome of the Panthéon.", "Umberto Eco's novel, which opens beside the pendulum in the Musée des Arts et Métiers."], "bib": ["Umberto Eco, <i>Il pendolo di Foucault</i>, 1988.", "John Oprea, “Geometry and the Foucault pendulum,” <i>American Mathematical Monthly</i> 102 (1995)."], "doors": [{"to": 4, "wall": "right", "title": "up, to the dome"}, {"to": 8, "wall": "left", "turn": "s", "look": "mirror", "title": "a door of silvered glass", "say": "You step through the glass. Left and right trade places."}], "objects": [{"kind": "ref", "icon": "book", "title": "Foucault's Pendulum", "by": "Umberto Eco", "note": "The novel opens beside the real one, in Paris."}]}, {"id": 8, "closed": "renovation", "name": "The Turning Room", "floor": "checker", "wing": "turnings", "decor": ["lamp", "rug"], "at": [4, 3], "text": "A square room, on purpose. Its symmetries are the eight in the corner of your screen: four turns and four flips. Hamilton's arcs are painted on a globe in the middle. Lay them head to tail and you have composed two rotations.\nSome of the doors in this wing turn you as you pass through them. Watch the F.", "mirror": "You came in through glass. The room is the same room, but the F in the corner is reversed, and something in the cellar is now visible that wasn't before.", "marginalia": ["The F in the menu bar is an element of D₄. Every door in the house can act on it."], "sources": ["Hamilton's quaternions (1843), carved into Brougham Bridge in Dublin, and his representation of rotations by arcs on the sphere."], "bib": ["Simon L. Altmann, <i>Rotations, Quaternions, and Double Groups</i>, 1986.", "John Stillwell, <i>Naive Lie Theory</i>, 2008."], "doors": [{"to": 1, "wall": "right"}, {"to": 7, "wall": "back", "turn": "s", "look": "mirror", "title": "a door of silvered glass", "say": "Through the glass again."}, {"to": 9, "wall": "left"}], "objects": [{"kind": "key", "item": "compass", "icon": "compass", "title": "A compass", "when": "mode:hardcore", "info": "A brass pocket compass. Held up (C), it shows true north in the room, which is how you notice a corridor that turned you."}, {"kind": "device", "icon": "turns", "title": "Hamilton's Turns", "href": "/turns/", "note": "Compose rotations by laying arcs head to tail on a sphere."}, {"kind": "device", "icon": "net", "title": "The SO(3) slide rule", "href": "/stereonet/", "hide": true, "note": "Also in the Observatory."}]}, {"id": 9, "closed": "renovation", "name": "The Card Room", "wing": "turnings", "decor": ["cardtables", "lamp"], "at": [3, 3], "text": "A green baize table, and a deck with only eight kinds of card: ±1, ±i, ±j, ±k. The left hand and the right hand play different games, since ij = k but ji = −k.\nA second table is set for a card game no one has invented yet. It's war, but the cards are group elements, and you win by making your stack equal to your opponent's.", "marginalia": ["In the simulations for Group War, the quaternion group gave about a 27% chance per turn of being able to equalize, against 56% for ℤ₄."], "sources": ["Hamilton's relations i² = j² = k² = ijk = −1, made into a card game."], "bib": ["John H. Conway and Derek A. Smith, <i>On Quaternions and Octonions</i>, 2003."], "doors": [{"to": 8, "wall": "right"}, {"to": 10, "wall": "back"}, {"to": 11, "wall": "left"}, {"to": 27, "wall": "front", "title": "salt air"}], "objects": [{"kind": "device", "icon": "cards", "title": "Quaternion Cards", "href": "/quaternion-cards/", "note": "A card game in the quaternion group."}, {"kind": "unwritten", "icon": "cards", "title": "Group War", "note": "Klein, ℤ₄, Q₈, S₃, D₄, octonions. In simulation, the chance of being able to equalize on a turn runs from about 0.56 (ℤ₄) down to about 0.12 (S₄)."}]}, {"id": 10, "closed": "renovation", "name": "The Lock Room", "wing": "turnings", "decor": ["lamp"], "at": [2, 2], "text": "A brass lock with four dials, and on its lid three equations. The dials hold the four roots of x⁴ − 2. Only the moves that keep the lid true are allowed, and those moves make up the Galois group.\nThe far door has the same lock built into it.", "marginalia": ["The lid's three relations are enough: any permutation that keeps them is one of the eight symmetries of the square of roots."], "sources": ["The standard textbook example of a Galois group that is dihedral."], "bib": ["David S. Dummit and Richard M. Foote, <i>Abstract Algebra</i>, 3rd ed., 2004, ch. 14.", "Ian Stewart, <i>Galois Theory</i>, 4th ed., 2015."], "doors": [{"to": 9, "wall": "right"}, {"to": 12, "wall": "left", "look": "dials", "title": "the locked door", "hint": "Its lock asks a question. Try the Galois Lock first.", "riddle": {"id": "galois", "q": "How many arrangements of the four dials will the lock ever reach?", "a": ["8", "eight"], "true": "Eight. The dials spin through the symmetries of a square, and the door swings open.", "false": "The dials stick. Count again, or go play with the lock on the table."}}], "objects": [{"kind": "device", "icon": "lock", "title": "Galois Lock", "href": "/symmetry-lock/", "note": "A lock whose moves are the Galois group of x⁴ − 2."}, {"kind": "unwritten", "icon": "lock", "title": "The General Galois Lock", "note": "Choose a polynomial and get a different lock."}]}, {"id": 11, "closed": "renovation", "name": "The Tile Room", "wing": "turnings", "decor": ["tilefloor", "dial", "lamp"], "at": [2, 4], "text": "The floor is a fifteen puzzle, tiles you can slide. Half of the arrangements can never be reached from the other half. A dial on the wall shows the sign of the permutation times (−1) to the distance of the blank, and that number never changes.\nThe door to the cellar turns you half around.", "marginalia": ["The floor shows the famous impossible position: 14 and 15 swapped. The parity dial says it can't be solved."], "sources": ["The 15 puzzle, a craze of 1880. Sam Loyd later claimed it, falsely, and offered a prize for swapping the 14 and 15."], "bib": ["W. W. Johnson and W. E. Story, “Notes on the ‘15’ puzzle,” <i>American Journal of Mathematics</i> 2 (1879).", "Jerry Slocum and Dic Sonneveld, <i>The 15 Puzzle</i>, 2006."], "doors": [{"to": 9, "wall": "right"}, {"to": 12, "wall": "back", "turn": "r2", "title": "a door that turns you around", "say": "You come out facing the way you came."}], "objects": [{"kind": "device", "icon": "tiles", "title": "Fifteen and the Parity Dial", "href": "/fifteen/", "note": "The 15 puzzle with its permutation, parity invariant, and commutators shown live."}]}, {"id": 12, "closed": "renovation", "name": "The Crystal Cellar", "floor": "stone", "wing": "turnings", "decor": ["lattice", "lamp"], "at": [1, 3], "text": "The walls are a crystal, one atom after another in a hexagonal lattice, except where they aren't. Walk a loop that would close in a perfect crystal. If it doesn't close, you have circled a dislocation, and the gap is the Burgers vector. It's a kind of holonomy too.", "mirror": "In the mirror, one wall of the cellar is a door.", "marginalia": ["The dashed red loop on the wall would close in a perfect crystal. The heavy red segment is the closure failure: the Burgers vector b. It is the holonomy of the lattice around the defect."], "sources": ["Volterra's dislocations (1907) and J. M. Burgers's circuits (1939)."], "bib": ["D. Hull and D. J. Bacon, <i>Introduction to Dislocations</i>, 5th ed., 2011."], "doors": [{"to": 10, "wall": "right"}, {"to": 11, "wall": "back", "turn": "r2"}, {"to": 22, "wall": "left", "when": "mirror", "twist": true, "look": "mirror", "title": "a door only mirrors show", "say": "You go through the door the mirror showed you."}], "objects": [{"kind": "device", "icon": "crystal", "title": "Defectsweeper", "href": "/defectsweeper/", "note": "Find dislocations hidden in a hexagonal crystal by walking Burgers circuits."}]}, {"id": 13, "closed": "renovation", "name": "The Great Spiral", "floor": "stone", "wing": "numbers", "decor": ["glacier", "stair", "shelves"], "at": [4, 6], "text": "A stair cut into ice winds down past shelf after shelf. The deeper the shelves, the older the numbers on them. Doors open off the landings. Some are marked for librarians of a certain rank. A visitor may look, but not take.", "again": "You know these landings now. The ice remembers your footprints longer than you would think.", "marginalia": ["Ranks here are earned by remembering rooms, not by age."], "sources": ["The Great Library of the Clayr in Garth Nix's <i>Lirael</i>, cut into a glacier, with its spiral ramp, its ranked assistant librarians, and its dangerous lower stacks."], "bib": ["Garth Nix, <i>Lirael</i>, 2001."], "phases": [{"when": "sheet:log!=0", "text": "This is landing {sheet:log}. The stair has turned under you: you came round a loop, and the loop came out a floor away."}, {"when": "sheet:log=-3", "text": "The lowest landing you have found. There is a door here that the plan doesn't show.", "doors": [{"to": 29, "wall": "right", "title": "the door on the lowest landing", "say": "Three landings down, the shelves stop pretending."}]}], "doors": [{"to": 1, "wall": "back", "turn": "r3", "title": "up, to the reading room", "say": "The stair unwinds you."}, {"to": 14, "wall": "left"}, {"to": 15, "wall": "right"}, {"to": 16, "wall": "front", "title": "further down", "lift": {"log": 1}}, {"to": 22, "wall": "back", "needs": "rank:3", "hint": "Closed stacks. Second Assistant Librarians and above. Remember more rooms.", "title": "the closed stacks"}], "objects": [{"kind": "device", "icon": "books", "title": "Ranks of the library", "action": "ranks", "note": "Every rank comes from remembering more rooms."}]}, {"id": 14, "closed": "renovation", "name": "The Tree of Distances", "wing": "numbers", "decor": ["glacier", "bigtree"], "at": [3, 7], "text": "A tree grows out of the ice, branching p ways at every level. Two numbers are close when they share a long trunk, that is, when their difference is divisible by a high power of p. In this room, 1 + 2 + 4 + 8 + … converges, to −1.", "marginalia": ["The tree drawn here branches three ways: p = 3."], "sources": ["Kurt Hensel's p-adic numbers (1897), and Ostrowski's theorem (1916) that these and the reals are all the completions of ℚ."], "bib": ["Fernando Q. Gouvêa, <i>p-adic Numbers: An Introduction</i>, 2nd ed., 1997."], "doors": [{"to": 13, "wall": "right"}, {"to": 15, "wall": "left"}], "objects": [{"kind": "device", "icon": "tree", "title": "p-adic Ruler", "href": "/p-adic/", "note": "A branching-tree ruler for p-adic distance."}]}, {"id": 15, "closed": "renovation", "name": "Funes's Room", "wing": "numbers", "shape": "square", "decor": ["gloom", "cot", "names"], "at": [2, 6], "text": "A dark room, lit only by the end of a cigarette. In Borges's story, Ireneo Funes lies here, unable to forget anything. He invented a numbering of his own in 1886 and soon passed twenty-four thousand. It began with his annoyance that the famous Thirty-Three gauchos took two signs and two words, not one. So every number got its own name.\nThe narrator objected, rightly, that this was the opposite of a number system. Saying 365 means three hundreds, six tens, and five ones. Funes's names have no place value, so they have no arithmetic. They are pure memory.", "again": "Funes remembers your last visit, and every step you took to get back here.", "widget": {"type": "funes", "names": [{"n": 7013, "name": "Máximo Pérez"}, {"n": 7014, "name": "The Railroad"}, {"n": 500, "name": "nine"}, {"n": 33, "name": "(the Thirty-Three: two signs, two words, the first irritation)"}, {"name": "Luis Melián Lafinur"}, {"name": "Olimar"}, {"name": "sulphur"}, {"name": "the reins"}, {"name": "the whale"}, {"name": "the gas"}, {"name": "the caldron"}, {"name": "Napoleon"}, {"name": "Agustín de Vedia"}, {"name": "meat blanket"}]}, "marginalia": ["The names on the wall are the ones Funes gives in the story. The text linked from this room is an English translation, where the “poncho full of meat” comes out as a “meat blanket.”"], "sources": ["Borges's “Funes el memorioso” (1942).", "A. R. Luria's case study of the mnemonist Solomon Shereshevsky, who also could not forget."], "bib": ["Jorge Luis Borges, “Funes the Memorious,” trans. James E. Irby, in <i>Labyrinths</i>, 1962.", "A. R. Luria, <i>The Mind of a Mnemonist</i>, 1968."], "doors": [{"to": 13, "wall": "right"}, {"to": 14, "wall": "back"}, {"to": 17, "wall": "left"}], "objects": [{"kind": "key", "item": "lantern", "icon": "lamp", "title": "A lantern", "when": "not:has:lantern"}, {"kind": "ref", "icon": "book", "title": "Funes the Memorious", "by": "Jorge Luis Borges", "href": "https://vigeland.caltech.edu/ist4/lectures/funes%20borges.pdf", "note": "The English translation quoted here. In it, the poncho full of meat is a “meat blanket.”"}]}, {"id": 16, "closed": "renovation", "name": "Lamé's Corridor", "shape": "corridor", "wing": "numbers", "decor": ["fibfloor", "glacier", "lamp"], "at": [4, 8], "text": "The corridor is an a × b rectangle. Each time you cut off the largest square that fits, the corridor narrows, and the squares are the steps of Euclid's algorithm. In 1844 Gabriel Lamé proved the first worst-case bound on an algorithm's running time: the number of steps is never more than five times the number of decimal digits of the smaller number.\nThe sharper form: at most ln b / ln φ + 1 steps. The longest corridors come from neighboring Fibonacci numbers, since each quotient is 1 and each square is as small as it can be. Find a corridor as long as the bound allows, and the last square drops something into your hand.", "widget": {"type": "euclid", "a": 89, "b": 34, "award": "golden-key", "awardText": "A golden key, stamped φ, falls out of the last square."}, "marginalia": ["The floor of the corridor is a golden rectangle cut into squares, the picture of Euclid's algorithm on two consecutive Fibonacci numbers, with the spiral through its squares. It is drawn in true perspective, so the squares shrink with distance as well as with the algorithm.", "The widget uses the bound from my write-up, n ≤ ln b / ln φ + 1 for the smaller number b."], "sources": ["Gabriel Lamé's 1844 note in the <i>Comptes rendus</i>, the first worst-case analysis of an algorithm."], "bib": ["W. Kusner, “Run time of the Euclidean algorithm” (notes).", "Ross Honsberger, <i>Mathematical Gems II</i>, MAA, 1976.", "Melvyn B. Nathanson, <i>Elementary Methods in Number Theory</i>, 1999.", "Jeffrey Shallit, “Origins of the analysis of the Euclidean algorithm,” <i>Historia Mathematica</i> 21 (1994).", "Donald E. Knuth, <i>The Art of Computer Programming</i>, vol. 2, §4.5.3."], "doors": [{"to": 13, "wall": "front", "title": "back up the stair", "lift": {"log": -1}}, {"to": 17, "wall": "back"}], "objects": [{"kind": "paper", "icon": "scroll", "title": "Run time of the Euclidean algorithm", "by": "W. Kusner", "note": "My write-up of Lamé's theorem, by way of Sierpiński, Grossman, and Nathanson."}]}, {"id": 17, "closed": "renovation", "name": "The Clock Room", "wing": "numbers", "decor": ["clockface", "lamp", "shelves"], "at": [2, 8], "text": "A clock with twelve hours, counted by twelves: dozens, grosses, great grosses. Bakers and hours both like twelve, because it divides by 2, 3, 4, and 6.\nOne door turns with the hour hand. It leads somewhere different every hour, and once in every four hours it leads to the center.", "widget": "clock", "phases": [{"when": "minutes:0-3", "text": "The clock is striking the hour, in dozens."}], "marginalia": ["The digits ↊ and ↋ are Isaac Pitman's dozenal digits, encoded in Unicode since 2015."], "sources": ["Bakers' dozens and grosses, the Dozenal Society, and the long history of counting by twelves."], "bib": ["Georges Ifrah, <i>The Universal History of Numbers</i>, 1999."], "doors": [{"to": 15, "wall": "right"}, {"to": 16, "wall": "front"}, {"to": [18, 19, 21, 23], "wall": "back", "label": "⟳", "oneway": true, "title": "the door on the clock's hand"}], "objects": [{"kind": "key", "item": "hourglass", "icon": "hourglass", "title": "An hourglass", "take": "You take the hourglass. Turn it (from your bag, or the clock in the tally bar) to set the house's time."}, {"kind": "unwritten", "icon": "clock", "title": "The Number Systems Museum", "note": "Tallies, Roman, Babylonian, Egyptian, Maya, Kaktovik, bases, the French counting words, dozen and gross, and Archimedes's Sand Reckoner."}, {"kind": "unwritten", "icon": "scroll", "title": "Continued fractions and nested radicals", "note": "Euclid's algorithm, written down differently."}]}, {"id": 18, "closed": "renovation", "name": "The Hexagon", "floor": "checker", "wing": "numbers", "shape": "hex", "decor": ["shelves", "lamp"], "at": [1, 7], "text": "Another hexagon, or the same one. Shelves on four walls, five shelves to a wall, thirty-two books to a shelf. The books are all different, and almost all of them are noise.\nThe shelves here fold. Take the door marked “?” and you could come out anywhere in the house.", "widget": "babel", "marginalia": ["Borges's books have 410 pages of 40 lines of about 80 characters, from 25 symbols. That is 25^1,312,000 books."], "sources": ["Borges's library, and Pratchett's L-space for the folding door.", "Jonathan Basile's online Library of Babel, which, like this room, can find any page you type."], "bib": ["William Goldbloom Bloch, <i>The Unimaginable Mathematics of Borges' Library of Babel</i>, 2008."], "phases": [{"when": "sheet:log!=0", "text": "These shelves belong to landing {sheet:log}. The books are the same as upstairs, with every letter shifted."}], "doors": [{"to": 17, "wall": "right"}, {"to": "random", "wall": "left", "label": "?", "look": "shelves", "title": "folded shelves", "say": "The shelves fold, and the corridor is shorter than it should be."}, {"to": 23, "wall": "back", "needs": "has:golden-key", "look": "gold", "hint": "A small gold lock with a φ on it.", "title": "the golden door"}], "objects": [{"kind": "ref", "icon": "book", "title": "The Library of Babel", "by": "Jorge Luis Borges"}]}, {"id": 19, "closed": "renovation", "name": "The Lily Pond", "wing": "pond", "decor": ["pool", "window", "woodcut"], "at": [6, 8], "text": "Lily pads crowd the water, as many as will fit without overlapping. How tightly can they pack, and how do you prove it? On the wall are Kepler's woodcuts of stacked cannonballs. Barlow's plans show the ways to stack layers of spheres, and the skeletons of FCC and HCP are drawn beside them. On a table by the water, the pads grow until they jam.", "phases": [{"when": "day", "text": "By day the lilies are open, and the packing is loose: every flower wants a little more room than its pad."}, {"when": "night|dusk", "text": "At night the lilies close. The pads lie flat and tight, and the packing is as good as it gets."}], "marginalia": ["The pads in the pond sit on a hexagonal lattice, the densest packing of equal disks in the plane (Thue; Fejes Tóth)."], "sources": ["Kepler's essay on the six-cornered snowflake (1611) and his conjecture about cannonballs; William Barlow's stackings of spheres (1883)."], "bib": ["Thomas C. Hales, “A proof of the Kepler conjecture,” <i>Annals of Mathematics</i> 162 (2005).", "J. H. Conway and N. J. A. Sloane, <i>Sphere Packings, Lattices and Groups</i>, 3rd ed., 1999.", "George G. Szpiro, <i>Kepler's Conjecture</i>, 2003."], "doors": [{"to": 20, "wall": "right"}, {"to": 21, "wall": "left"}, {"to": 17, "wall": "front"}, {"to": 26, "wall": "back", "title": "the model room"}, {"to": 34, "wall": "right", "title": "the garden gate"}], "objects": [{"hidden": true, "kind": "page", "icon": "pond", "title": "Packing Problems", "href": "/packing/", "note": "The packing page, still being furnished."}, {"kind": "device", "icon": "pond", "title": "Lily Pads", "href": "/lily-pads/", "note": "Sticky growth: pads grow until they jam, letting go only when a contact is pulled apart."}, {"hidden": true, "kind": "figure", "icon": "hex", "title": "Kepler's woodcuts", "href": "/assets/figures/keplerwoodcut1.pdf", "note": "<a href='/assets/figures/keplerwoodcut1.pdf'>one</a>, <a href='/assets/figures/keplerwoodcut2.pdf'>two</a>, <a href='/assets/figures/woodcutabcde.pdf'>lettered</a>"}, {"hidden": true, "kind": "figure", "icon": "hex", "title": "Barlow's plans", "href": "/assets/figures/barlowplans.pdf", "note": "<a href='/assets/figures/barlow.pdf'>Barlow</a>, <a href='/assets/figures/barlowplans5.pdf'>plans 5</a>, <a href='/assets/figures/barlowplanse.pdf'>plans e</a>"}, {"hidden": true, "kind": "figure", "icon": "crystal", "title": "FCC and HCP", "href": "/assets/figures/fccskel.pdf", "note": "<a href='/assets/figures/fccskel.pdf'>FCC skeleton</a>, <a href='/assets/figures/hcpskel.pdf'>HCP skeleton</a>, <a href='/assets/figures/icoskel.pdf'>icosahedral</a>, <a href='/assets/figures/FCCstress.pdf'>FCC stress</a>, <a href='/assets/figures/HCPstress.pdf'>HCP stress</a>"}, {"hidden": true, "kind": "figure", "icon": "hex", "title": "Contact graphs, n = 3 to 14", "href": "/assets/figures/n12.pdf", "note": "<a href='/assets/figures/n3.pdf'>3</a> <a href='/assets/figures/n6.pdf'>6</a> <a href='/assets/figures/n9.pdf'>9</a> <a href='/assets/figures/n12.pdf'>12</a> <a href='/assets/figures/n13.pdf'>13</a> <a href='/assets/figures/n14.pdf'>14</a>"}, {"hidden": true, "kind": "figure", "icon": "crystal", "title": "Bottlenecks", "href": "/assets/figures/bottleneck1.pdf"}]}, {"id": 20, "closed": "renovation", "name": "The Schoolroom", "wing": "schoolroom", "decor": ["chalkboard", "desks", "lamp"], "at": [7, 6], "text": "Desks, a chalkboard, and a box of cards. This is where the devices get used for practice: fractions first, then whatever MATH 102 and 103 need next.", "phases": [{"when": ["weekday", "hours:8-17"], "text": "Class is in session. Somebody is at the board finding a common denominator."}, {"when": "night|weekend", "text": "The chairs are up on the desks. The chalk tray has been wiped, mostly."}], "marginalia": ["The board shows the step students skip: rewriting over the least common denominator before adding."], "sources": ["Practice games for MATH 102; Fraction Target is a fraction-card cousin of the game 24."], "doors": [{"to": 0, "wall": "back", "title": "the Entry"}, {"to": 6, "wall": "right"}, {"to": 19, "wall": "left"}, {"to": 24, "wall": "front", "title": "the lecture wing"}, {"to": 28, "wall": "right", "title": "a small door, painted"}], "objects": [{"kind": "device", "icon": "fraction", "title": "Fraction Target", "href": "/fraction-target/", "note": "Make the target from four fraction cards. Every deal can be solved."}, {"kind": "unwritten", "icon": "fraction", "title": "Coefficient Knobs", "note": "Turn a, b, and c on a quadratic and watch the vertex trace its locus. Then cubics, and the cusp 4p³ + 27q² = 0."}]}, {"id": 21, "closed": "renovation", "name": "The Workshop", "wing": "workshop", "decor": ["workbench", "lamp", "window", "shelves"], "at": [6, 7], "text": "Sawdust, plaster, and drafts. The shelf by the door holds the books that aren't written yet. They are real books in every respect except that they don't exist.\nA linking book lies open on the bench. Touch the picture and you're back in the reading room.", "phases": [{"when": "night", "text": "The plaster in the molds is setting overnight. Don't touch it."}], "marginalia": ["The shelf of unwritten books is the house's to-do list. When one gets written, it moves out to its room."], "sources": ["The shelf of books never written, from the library of Dream in Neil Gaiman's <i>The Sandman</i>.", "The linking books of Myst (1993).", "The plaster models of the Brill and Schilling collections."], "bib": ["Neil Gaiman, <i>The Sandman</i>, 1989–1996.", "Cyan, <i>Myst</i>, 1993."], "doors": [{"to": 19, "wall": "right"}, {"to": 16, "wall": "left", "oneway": true}], "objects": [{"kind": "link", "icon": "book", "title": "A linking book: the reading room", "to": 1, "say": "The picture swallows you."}, {"kind": "unwritten", "icon": "unwritten", "title": "SO(3) Lab Manual", "note": "Building the stereonet slide rule, with printables. A draft exists."}, {"kind": "unwritten", "icon": "unwritten", "title": "The Handbook", "note": "Circular rules, root systems, Dynkin diagrams, and finite fields. 37 pages of draft."}, {"kind": "unwritten", "icon": "unwritten", "title": "Plaster molds", "note": "3D-printed molds for plaster models of the objects in the book."}, {"kind": "unwritten", "icon": "unwritten", "title": "The G₂ rule and the sl(3) rule", "note": "Root-system slide rules on transparencies."}]}, {"id": 22, "name": "The Archive", "floor": "stone", "ceiling": "vault", "wing": "archive", "shape": "oct", "decor": ["catalogshelves", "lamp", "rug", "cardcatalog"], "at": [0, 5], "text": "An eight-sided vault lined with shelves, and the shelves are the catalogue: every book, record, object, and scrap the house holds has a place here, and its spine says what it is. Take one down to read its entry.\nIn the middle, on a podium, lies the log book. Anyone may read it and search it. Only the archivist can write in it.\nThe other doors are boarded for now. The way back is the linking book on its stand.", "marginalia": ["Secret rooms count toward rank but not toward the room total."], "sources": ["The finis Africae, the walled-up room at the heart of the library in Eco's <i>The Name of the Rose</i>."], "bib": ["Umberto Eco, <i>Il nome della rosa</i>, 1980."], "doors": [{"to": 12, "wall": "right", "turn": "s", "twist": true, "title": "back through the mirror"}, {"to": 13, "wall": "left", "title": "the closed stacks"}, {"to": 23, "wall": "back", "needs": "has:golden-key", "oneway": true, "look": "gold", "hint": "A small gold lock with a φ on it."}, {"to": 29, "wall": "front", "title": "the stacks beyond the stacks"}], "objects": [{"kind": "device", "icon": "logbook", "mount": "center", "title": "The log book", "action": "logbook", "note": "The catalogue of everything in the house: search it, read the entries, and, if you're the archivist, add to it."}, {"kind": "device", "icon": "linkbook", "mount": "pedestal", "wall": "front", "title": "A linking book: the Office", "action": "link", "to": 35, "note": "Its panel shows the office, moving faintly. Touch it to go there."}, {"kind": "key", "item": "finding-aid", "icon": "scroll", "title": "The finding aid", "when": "mode:hardcore", "info": "The house's catalogue in a ledger: everything in every room, listed plainly, for when you would rather look it up than walk."}, {"hidden": true, "kind": "paper", "icon": "scroll", "title": "My papers", "href": "/research/", "info": "The curator's research papers, filed here as they are written."}, {"hidden": true, "kind": "paper", "icon": "scroll", "title": "Die Presse, April 2017", "href": "/assets/DiePresse2017422.pdf"}, {"kind": "device", "icon": "calcab", "mount": "pedestal", "wall": "left", "title": "The calendar cabinet", "action": "calendars", "note": "Today in sixteen calendars, and the one the house keeps."}, {"kind": "device", "icon": "tkcase", "mount": "pedestal", "wall": "right", "title": "The case of timekeepers", "action": "timekeepers", "note": "Hourglass, water clock, candle clock, incense seal, wadokei, decimal clock, and Italian hours: choose one for the Entry desk."}]}, {"id": 23, "closed": "renovation", "name": "The Center", "wing": "archive", "secret": true, "shape": "round", "decor": ["lamp", "rug", "stars"], "at": [-1, 6], "text": "A round room with nothing in it but a count. Every maze is really a question about its shortest path.", "widget": "center", "marginalia": ["The Center compares your path with the shortest one, computed by breadth-first search over every door."], "sources": ["Christopher Manson's <i>Maze</i>, whose 45 numbered rooms hide a shortest path of 16 steps from the entrance to the center and back."], "bib": ["Christopher Manson, <i>Maze: Solve the World's Most Challenging Puzzle</i>, 1985."], "doors": [{"to": 1, "wall": "back", "oneway": true, "title": "straight out to the reading room"}, {"to": 18, "wall": "left"}], "objects": [{"kind": "note", "icon": "note", "title": "A note in my hand", "note": "If you got here, write and tell me which way you came."}]}, {"id": 24, "name": "The Lecture Hall", "closed": true, "wing": "lectures", "shape": "round", "decor": ["screen", "tiers", "lamp"], "at": [8, 7], "text": "Tiered benches and a chalk tray. Slides from fifteen years of talks are stacked in the projection booth, by date, which is the only order a speaker can keep.", "marginalia": ["Titles are by venue and date. Talk titles can be added in the data file."], "sources": ["The talks folder of this site, <span class='mono'>/assets/</span>."], "doors": [{"to": 20, "wall": "left"}, {"to": 25, "wall": "right"}, {"to": 26, "wall": "back"}], "objects": [{"hidden": true, "kind": "talk", "icon": "scroll", "title": "Isaac Newton Institute, November 2012", "href": "/assets/2012_3NovINITalk.pdf"}, {"hidden": true, "kind": "talk", "icon": "scroll", "title": "An overview, November 2013", "href": "/assets/2013_11Overview.pdf"}, {"hidden": true, "kind": "talk", "icon": "scroll", "title": "Dissertation defense, May 2014", "href": "/assets/2014_5Defense.pdf"}, {"hidden": true, "kind": "talk", "icon": "scroll", "title": "ESI Vienna, October 2014", "href": "/assets/2014_10ESI.pdf"}, {"hidden": true, "kind": "talk", "icon": "scroll", "title": "Aalto, November 2014", "href": "/assets/2014_11Aalto.pdf"}, {"hidden": true, "kind": "talk", "icon": "scroll", "title": "ICERM, discrepancy, April 2015", "href": "/assets/2015_4ICERMDISCREPANCY.pdf"}, {"hidden": true, "kind": "talk", "icon": "scroll", "title": "Doctoral seminar, December 2015", "href": "/assets/2015_12DocZTSeminar.pdf"}, {"hidden": true, "kind": "talk", "icon": "scroll", "title": "Advanced topics, January 2016", "href": "/assets/2016_1JanAdvancedTopics.pdf"}, {"hidden": true, "kind": "talk", "icon": "scroll", "title": "AMS, March 2016", "href": "/assets/2016_3AMSTalk.pdf"}, {"hidden": true, "kind": "talk", "icon": "scroll", "title": "Pittsburgh, August 2016", "href": "/assets/2016_8PittTalk.pdf"}, {"hidden": true, "kind": "talk", "icon": "scroll", "title": "Stanford, August 2016", "href": "/assets/2016_8StanfordTalk/StanfordTalk.pdf"}, {"hidden": true, "kind": "talk", "icon": "scroll", "title": "AIM, September 2016", "href": "/assets/2016_9AIMTALK.pdf"}, {"hidden": true, "kind": "talk", "icon": "scroll", "title": "Geometry talk, September 2016", "href": "/assets/2016_9GeometryTalk/2016GeometryTalk.pdf"}, {"hidden": true, "kind": "talk", "icon": "scroll", "title": "Spain, April 2017", "href": "/assets/2017_4Spain.pdf"}, {"hidden": true, "kind": "talk", "icon": "scroll", "title": "Leoben, June 2017", "href": "/assets/2017_6LeobenTalk.pdf"}, {"hidden": true, "kind": "talk", "icon": "scroll", "title": "ICERM, March 2018", "href": "/assets/2018_3ICERM.pdf"}, {"hidden": true, "kind": "talk", "icon": "scroll", "title": "ICERM, April 2018", "href": "/assets/2018_4ICERM.pdf"}, {"hidden": true, "kind": "talk", "icon": "scroll", "title": "ICERM, 2018 (slides with point sets)", "href": "/assets/2018ICERM/slides.pdf"}, {"hidden": true, "kind": "talk", "icon": "scroll", "title": "CMO Oaxaca, October 2019", "href": "/assets/2019_10CMO.pdf"}]}, {"id": 25, "name": "The Seminar Room", "closed": true, "wing": "lectures", "decor": ["longtable", "shelves", "lamp"], "at": [9, 8], "text": "A long table, and the notes from a graduate course spread across it in the order the lectures went: classification, ensembles, and the rest. Along with them are a problem book and the statements I wrote to explain what I was doing.", "sources": ["Course notes and statements from <span class='mono'>/assets/</span>."], "doors": [{"to": 24, "wall": "left"}, {"to": 26, "wall": "back"}], "objects": [{"hidden": true, "kind": "paper", "icon": "scroll", "title": "Research statement", "href": "/assets/KusnerResearchStatement.pdf"}, {"hidden": true, "kind": "paper", "icon": "scroll", "title": "Research statement, short", "href": "/assets/KusnerResearchStatementShort.pdf"}, {"hidden": true, "kind": "paper", "icon": "scroll", "title": "Bounds via slicing", "href": "/assets/Boundsviaslicing.pdf"}, {"hidden": true, "kind": "paper", "icon": "book", "title": "Problem book", "href": "/assets/Problembook.pdf"}, {"hidden": true, "kind": "notes", "icon": "note", "title": "MAT 670, notes 1", "href": "/assets/MAT670_1.pdf"}, {"hidden": true, "kind": "notes", "icon": "note", "title": "MAT 670, notes 2", "href": "/assets/MAT670_2.pdf"}, {"hidden": true, "kind": "notes", "icon": "note", "title": "MAT 670, notes 3", "href": "/assets/MAT670_3.pdf"}, {"hidden": true, "kind": "notes", "icon": "note", "title": "MAT 670, notes 4–6", "href": "/assets/MAT670_46.pdf"}, {"hidden": true, "kind": "notes", "icon": "note", "title": "MAT 670, notes 7–8", "href": "/assets/MAT670_78.pdf"}, {"hidden": true, "kind": "notes", "icon": "note", "title": "MAT 670, notes 9–10", "href": "/assets/MAT670_9X.pdf"}, {"hidden": true, "kind": "notes", "icon": "note", "title": "MAT 670, notes 11", "href": "/assets/MAT670_XI.pdf"}, {"hidden": true, "kind": "notes", "icon": "note", "title": "MAT 670, classification", "href": "/assets/MAT670_classification.pdf"}, {"hidden": true, "kind": "notes", "icon": "note", "title": "MAT 670, ensembles", "href": "/assets/MAT670_emsemble.pdf"}]}, {"id": 26, "name": "The Model Room", "closed": true, "wing": "lectures", "decor": ["polytope", "window", "stars"], "at": [7, 9], "text": "Things that move or can be printed. A snub 24-cell turns in a loop. Points spread over a sphere, some at random, some on a Fibonacci spiral, and some on purpose, and their discrepancy is graphed underneath. On the shelf is a printable solid.", "marginalia": ["The hanging model is an icosahedron. The snub 24-cell is built from 24 icosahedra and 120 tetrahedra."], "sources": ["Thorold Gosset's snub 24-cell (1900), and the point sets from the discrepancy project."], "bib": ["H. S. M. Coxeter, <i>Regular Polytopes</i>, 3rd ed., 1973."], "doors": [{"to": 24, "wall": "back"}, {"to": 25, "wall": "right"}, {"to": 19, "wall": "left", "title": "toward the water"}], "objects": [{"hidden": true, "kind": "model", "icon": "hex", "title": "The snub 24-cell, turning", "href": "/assets/2016_9GeometryTalk/snub24.mov"}, {"hidden": true, "kind": "model", "icon": "net", "title": "Point sets on the sphere (movie)", "href": "/assets/2018ICERM/32movie.mov"}, {"hidden": true, "kind": "model", "icon": "box", "title": "A printable solid (HRT.stl)", "href": "/assets/HRT.stl"}, {"hidden": true, "kind": "figure", "icon": "net", "title": "Fibonacci points, 5000", "href": "/assets/2018ICERM/fib5000.pdf"}, {"hidden": true, "kind": "figure", "icon": "net", "title": "Spiral discrepancy", "href": "/assets/2018ICERM/spiraldiscrepancy.pdf"}, {"hidden": true, "kind": "figure", "icon": "net", "title": "Random discrepancy", "href": "/assets/2018ICERM/randomdiscrepancy.pdf"}, {"hidden": true, "kind": "figure", "icon": "net", "title": "Discrepancy samples", "href": "/assets/2018ICERM/discrepancysamples.pdf"}]}, {"id": 27, "closed": "renovation", "name": "The Island of Two Kinds", "wing": "turnings", "decor": ["sand", "window", "sea"], "at": [3, 1], "text": "Sand on the floor and two doors in the back wall. The islanders here come in two kinds: knights, who always tell the truth, and knaves, who always lie. Raymond Smullyan collected them by the hundred.\nEach puzzle is dealt fresh, and each has exactly one answer. A solver checks every possible world before the islanders speak. Solve three and the barred door at the far end of the beach opens.", "widget": {"type": "knights", "need": 3}, "marginalia": ["Every puzzle here is generated, then checked against every assignment of knights and knaves and every choice of door. Only puzzles with one right door are shown."], "sources": ["Raymond Smullyan's island of knights and knaves."], "bib": ["Raymond Smullyan, <i>What Is the Name of This Book?</i>, 1978.", "Raymond Smullyan, <i>The Lady or the Tiger?</i>, 1982.", "Raymond Smullyan, <i>To Mock a Mockingbird</i>, 1985.", "Raymond Smullyan, <i>Forever Undecided</i>, 1987."], "doors": [{"to": 9, "wall": "front", "title": "back to the card room"}, {"to": 10, "wall": "back", "oneway": true}, {"to": 12, "wall": "back", "oneway": true, "needs": "solved:island", "look": "bars", "hint": "Barred. Solve three puzzles on the island.", "title": "the barred door", "say": "The bar lifts. You go down to the cellar."}], "objects": [{"kind": "ref", "icon": "book", "title": "The Lady or the Tiger?", "by": "Raymond Smullyan"}, {"kind": "ref", "icon": "book", "title": "Forever Undecided", "by": "Raymond Smullyan", "note": "Knights and knaves, all the way up to Gödel."}, {"kind": "unwritten", "icon": "tree", "title": "The Mockingbird Forest", "note": "Smullyan's birds as combinators: S, K, and the mockingbird M, where Mx = xx. A device for composing them."}]}, {"id": 28, "closed": "renovation", "name": "The Nursery", "wing": "schoolroom", "decor": ["lowshelves", "window", "lamp", "rug"], "at": [9, 6], "text": "A small room with low shelves. On the rug lies a book bound in something that isn't quite leather. In Stephenson's novel, the Primer was a book that raised the girl who read it, teaching her through stories that rewrote themselves around her.\nThis one is humbler. It knows where you have been in the house and where you haven't. Pick it up and it will travel with you.", "marginalia": ["The Primer's lessons are stored at the bottom of the data file, one per room."], "sources": ["The interactive book of Neal Stephenson's novel, which raises the girl who reads it."], "bib": ["Neal Stephenson, <i>The Diamond Age: Or, A Young Lady's Illustrated Primer</i>, 1995."], "doors": [{"to": 20, "wall": "left"}], "objects": [{"kind": "primer", "icon": "book", "title": "A Young Lady's Illustrated Primer", "action": "primer", "item": "primer", "note": "Open it here, or anywhere once it's in your pocket."}, {"kind": "ref", "icon": "book", "title": "The Diamond Age", "by": "Neal Stephenson"}]}, {"id": 29, "closed": "renovation", "name": "The Hall of Impossible Libraries", "floor": "stone", "ceiling": "vault", "wing": "archive", "secret": true, "shape": "oct", "decor": ["shelves", "lamp", "stars", "alethiometer"], "at": [-1, 4], "text": "The shelves here hold the libraries that never were, or not quite: the great stores of knowledge from other people's books. Every one of them is a different answer to the question this house asks, which is what it means to keep everything you know in one place and still be able to find it.\nIn the middle of the room stands an instrument with thirty-six symbols and three hands.", "widget": "oracle", "marginalia": ["The alethiometer here is my own: its symbols are things in the house, and it answers with a room. The same three hands give the same answer all day, and a different one tomorrow."], "sources": ["The libraries and instruments on the shelves, each credited on its card."], "bib": ["Vannevar Bush, “As We May Think,” <i>The Atlantic</i>, July 1945.", "Ramon Llull, <i>Ars generalis ultima</i>, 1305–1308.", "Philip Pullman, <i>Northern Lights</i>, 1995.", "Frank Herbert, <i>Dune</i>, 1965.", "J. R. R. Tolkien, <i>The Lord of the Rings</i>, 1954–55.", "Susan Cooper, <i>The Dark Is Rising</i>, 1973.", "Isaac Asimov, <i>Foundation</i>, 1951.", "Ursula K. Le Guin, <i>A Wizard of Earthsea</i>, 1968.", "Terry Pratchett, <i>Guards! Guards!</i>, 1989."], "doors": [{"to": 22, "wall": "front", "title": "back to the Archive"}, {"to": "random", "wall": "left", "label": "?", "look": "shelves", "title": "a gap between two shelves", "say": "All libraries are connected. You come out somewhere else."}], "objects": [{"kind": "ref", "icon": "scroll", "title": "An STC fragment", "by": "Warhammer 40,000", "note": "A Standard Template Construct, the data-seed of a whole lost technology. Recovering a complete one is a holy act. Every device in this house is meant to be a small STC."}, {"kind": "ref", "icon": "book", "title": "The Orange Catholic Bible, and a Mentat", "by": "Frank Herbert, Dune", "note": "After the Butlerian Jihad outlawed thinking machines, people trained their own minds to compute. A slide rule is a polite compromise."}, {"kind": "ref", "icon": "book", "title": "The Red Book of Westmarch", "by": "J. R. R. Tolkien", "note": "Also the archives of Minas Tirith, where a forgotten scroll mattered more than any army."}, {"kind": "ref", "icon": "net", "title": "A palantír", "by": "J. R. R. Tolkien", "note": "A seeing-stone. Compare the Observatory's dome, which only shows what is really there."}, {"kind": "ref", "icon": "book", "title": "The Book of Gramarye", "by": "Susan Cooper, The Dark Is Rising", "note": "Read once and then destroyed; what it taught survives only in memory. Funes would have been the ideal reader."}, {"kind": "ref", "icon": "clock", "title": "The alethiometer", "by": "Philip Pullman, His Dark Materials", "note": "Thirty-six symbols, each with endless meanings, read by setting three hands. The house keeps a crude copy in the middle of this room."}, {"kind": "ref", "icon": "books", "title": "The Great Library of the Clayr", "by": "Garth Nix, Lirael", "note": "A library carved into a glacier, with ranked librarians and stacks that bite. The Great Spiral is its cousin."}, {"kind": "ref", "icon": "books", "title": "The Aedificium", "by": "Umberto Eco, The Name of the Rose", "note": "A labyrinth built as a library, with the finis Africae hidden at its heart."}, {"kind": "ref", "icon": "hex", "title": "The Library of Babel", "by": "Jorge Luis Borges", "note": "Every possible book, in hexagons without end."}, {"kind": "ref", "icon": "books", "title": "L-space", "by": "Terry Pratchett", "note": "Enough books in one place bend space, and all libraries become one library."}, {"kind": "ref", "icon": "book", "title": "The Encyclopedia Galactica", "by": "Isaac Asimov, Foundation", "note": "A library compiled as a cover story for a plan."}, {"kind": "ref", "icon": "scroll", "title": "The Isolate Tower", "by": "Ursula K. Le Guin, Earthsea", "note": "Where the Master Namer keeps the lists of true names."}, {"kind": "ref", "icon": "hex", "title": "Llull's Ars Magna", "by": "Ramon Llull, c. 1305", "note": "Real: nested paper wheels that combine concepts mechanically. Leibniz read it. It belongs in the Instrument Gallery."}, {"kind": "ref", "icon": "scroll", "title": "The memex", "by": "Vannevar Bush, “As We May Think,” 1945", "note": "Real: a desk that stores a whole library and the trails a reader makes through it. The nearest ancestor of this house."}, {"kind": "ref", "icon": "books", "title": "The Library of Alexandria", "note": "Real, and lost."}, {"kind": "ref", "icon": "scroll", "title": "The Voynich manuscript", "note": "Real, and still unread."}, {"kind": "unwritten", "icon": "hex", "title": "Llull's wheels", "note": "A working volvelle of Llull's combinatorial wheels."}, {"kind": "ref", "icon": "book", "title": "The Hitchhiker's Guide to the Galaxy", "by": "Douglas Adams", "note": "A guide to everything, wrong in places, with a reassuring cover. The finding aid aspires to its brevity."}, {"kind": "ref", "icon": "books", "title": "The Book of Days", "by": "Robert Chambers, 1864", "note": "Real: a miscellany for every day of the year, of anniversaries, customs, and curiosities. The notice board's ancestor."}, {"kind": "ref", "icon": "book", "title": "The Book of Sand", "by": "Jorge Luis Borges", "note": "A book with no first page and no last, whose pages cannot be found twice. All possible futures, bound in cloth."}, {"kind": "ref", "icon": "books", "title": "Serie's magic", "by": "Kanehito Yamada and Tsukasa Abe, Frieren: Beyond Journey's End", "note": "The mage who has gathered nearly all the magic in the world. Frieren herself collects grimoires of small, useless spells, slowly, over centuries, the way an elf keeps a library."}, {"kind": "unwritten", "icon": "books", "title": "Shelves for the media collection", "note": "Films, music, and books from the collection, to be shelved here and in the stacks."}]}, {"id": 0, "name": "The Entry", "wing": "foyer", "floor": "checker", "ceiling": "coffers", "decor": ["thermo", "window", "lamp", "rose", "wainscot", "porter"], "at": [5, 7], "text": "A high, empty hall. Someone has just left: there is a letter on the desk, a lamp still lit, and the things they meant you to have laid out beside it. A compass rose in the floor points to true north. The thermometer and the window show the real weather outside.\nOn the left wall hangs the notice board with this week's problem. On the right are the link board, which goes everywhere directly, and the almanac. Ahead are two doors: the reading room, and the tall arch into the Great Hall. The office is behind you.", "again": "The hall is as you left it. The letter is still on the desk.", "doors": [{"to": 1, "wall": "back", "title": "the reading room"}, {"to": 42, "wall": "back", "title": "the great hall"}, {"to": 34, "wall": "left", "title": "out to the sundial court"}, {"to": 20, "wall": "right", "title": "the schoolroom"}, {"to": 35, "wall": "front", "title": "the office"}], "objects": [{"wall": "back", "kind": "letter", "icon": "note", "title": "A letter, left on the desk", "action": "letter", "info": "A letter from the curator to whoever walks in first: what the house is, and how to get about in it. Read it again any time."}, {"wall": "back", "kind": "key", "item": "master-key", "icon": "key", "title": "A ring of keys", "take": "You take the ring of keys. Every ordinary lock will open for you now.", "info": "The master key. It opens every door that has a lock, though not the ones that open only for a reason."}, {"wall": "back", "kind": "key", "item": "plan", "icon": "map", "title": "The full plan", "take": "You take the full plan of the house.", "info": "The whole house drawn out, every room and door, including the ones still closed for renovation."}, {"wall": "back", "kind": "key", "item": "map", "icon": "map", "title": "A folded map", "take": "You take the folded map. It fills in as you walk.", "info": "A map that fills itself in as you walk: rooms appear on it once you have stood in them."}, {"wall": "back", "kind": "key", "item": "compass", "icon": "compass", "title": "A compass", "take": "You take the compass. It will always tell you which way is true.", "info": "A brass pocket compass. Held up (C), it shows true north in the room, which is how you notice a corridor that turned you."}, {"wall": "back", "kind": "device", "icon": "book", "title": "The guest book", "action": "register", "note": "Sign it, and the Primer will know your name."}, {"wall": "back", "kind": "device", "icon": "bell", "title": "A brass bell", "action": "bell", "info": "A porter's bell. Ring it and someone, somewhere in the house, may hear."}, {"wall": "back", "kind": "device", "icon": "tray", "title": "A tray for putting things back", "action": "return", "note": "Return what you took from the desk."}, {"kind": "device", "mount": "board", "wall": "left", "icon": "note", "title": "The notice board", "action": "notices", "note": "The problem of the week, the calendar, news, and a wanted card."}, {"kind": "device", "icon": "note", "wall": "left", "title": "The codes ledger", "action": "codes", "note": "Your save code, and a place to type warp words."}, {"kind": "device", "mount": "board", "wall": "right", "icon": "map", "title": "The link board", "action": "links", "note": "Every page of the site, and your own tiles."}, {"kind": "device", "mount": "board", "wall": "right", "icon": "clock", "title": "The almanac", "action": "almanac", "note": "The weather now and for the next few days, sunrise and sunset, and the moon and planets tonight."}, {"kind": "device", "icon": "musicbox", "wall": "right", "item": "musicbox", "portable": true, "action": "music", "title": "A music box", "note": "Take it with you. Opened, it is a workshop: music made as it plays in many scales and tunings, rooms to play it in (made, measured, or loaded), a lab for convolving sounds, the radio, and a little sonar."}, {"kind": "key", "item": "primer", "icon": "book", "wall": "back", "title": "A Young Lady's Illustrated Primer", "when": "not:has:primer", "note": "The house's field guide. Touch any glint of light over a thing and the Primer writes down what it is; open it to read your notes, and for the house's lessons."}, {"kind": "device", "icon": "carriage", "wall": "right", "title": "A carriage clock", "action": "clock", "note": "It keeps house time and chimes the quarters: Westminster, Whittington, St. Michael's, ting-tang, or ship's bells."}, {"kind": "key", "item": "lantern", "icon": "lamp", "wall": "front", "title": "A lantern on a hook", "info": "A lantern for the dark rooms. Its flame can be coloured with salts: strontium red, copper blue, sodium yellow."}, {"kind": "key", "item": "finding-aid", "icon": "scroll", "wall": "front", "title": "The finding aid", "take": "You take the finding aid: every room and thing, listed plainly.", "info": "The house's catalogue in a ledger: everything in every room, listed plainly, for when you would rather look it up than walk."}], "marginalia": ["This is the front door, and a launch page: the link board is one click away from here, and pressing / anywhere in the house lets you type to go."], "sources": ["The opening of Myst, where you are dropped on a dock with nothing in your hands and a note to find."]}, {"id": 34, "name": "The Sundial Court", "wing": "court", "floor": "stone", "ceiling": "open", "size": 22, "walk": true, "decor": ["sundial", "cloister", "dialcabinet"], "at": [5, 8], "text": "A wide open court, twenty-two meters across, with the real sky over it and a sundial in the middle, laid out for the latitude where the house stands (Appleton, unless the astrolabe has carried it off). Walk anywhere on the paving, and click the sky to go up into it. The shadow on the plate is the actual shadow for this moment, or for whatever moment the hourglass says. Look up: the sky is the sky over the court right now, sun or stars, the moon in its true phase, and as much cloud as the weather says.\nUnder the colonnade stands a glass-fronted cabinet of dials: the horizontal dial, an armillary sphere, a mean-time dial of figure-eights, a glass sphere that throws a spot of sun across the paving, and a little noon cannon. Open it and choose which one stands in the court.\nOn a clear night with a bright moon the dial works by moonlight. It tells moon time, read straight off the plate, which runs about forty-eight minutes later each night than sun time.\nThe dial tells sun time, which is not clock time. The difference is the longitude, the time zone, daylight saving, and the equation of time, the wobble that comes from the earth's tilted, elliptical orbit.", "widget": "sundial", "doors": [{"to": 0, "wall": "right", "title": "back to the Entry"}, {"to": 19, "wall": "back", "title": "the lily pond"}, {"to": 36, "wall": "front", "title": "the garden gate", "look": "gate"}], "objects": [{"kind": "device", "icon": "astrolabe", "wall": "right", "item": "astrolabe", "portable": true, "action": "astrolabe", "title": "An astrolabe with a storm glass", "note": "Turn the rete to stand somewhere else under the sky, or at another hour; tap the storm glass to change the weather."}], "marginalia": ["Hour lines: tan θ = sin φ · tan h. At the pole they'd be evenly spaced; at the equator they all crowd toward six o'clock."], "bib": ["René R. J. Rohr, <i>Sundials: History, Theory, and Practice</i>, 1970.", "Jean Meeus, <i>Astronomical Algorithms</i>, 1991, for the sun and moon (here in their low-precision forms).", "Albert E. Waugh, <i>Sundials: Their Theory and Construction</i>, 1973."]}, {"id": 30, "closed": "renovation", "name": "The North Arcade", "wing": "branch", "floor": "checker", "decor": ["pillar", "lamp"], "at": [9, 2], "text": "Four arcades surround a single pillar marked 0. It is a branch point. Every number has two square roots, and as you walk around zero you cannot keep choosing the same one. Go around the pillar once and you are on the other sheet. Go around again and you are back.", "phases": [{"when": "sheet:sqrt=1", "name": "The North Arcade, other sheet", "text": "This is the other sheet. The arcade looks the same, but the lettering on the pillar runs the other way."}], "doors": [{"to": 31, "wall": "right"}, {"to": 33, "wall": "left", "lift": {"sqrt": -1}}], "objects": [{"kind": "device", "icon": "scroll", "title": "A table for mending paper", "action": "combine", "uses": ["page-left", "page-right"], "gives": "mended-page", "solve": "mended", "say": "The two halves fit. The torn edge disappears.", "hint": "You need both halves of the torn page. They are on different sheets."}], "marginalia": ["Monodromy, not holonomy: the loop doesn't turn you, it changes which room you arrive in. The square root's Riemann surface has two sheets glued along a cut."]}, {"id": 31, "closed": "renovation", "name": "The East Arcade", "wing": "branch", "floor": "checker", "decor": ["pillar", "lamp"], "at": [10, 2], "text": "The second side of the pillar. A plaque reads: √1 = 1, but it is also −1.", "phases": [{"when": "sheet:sqrt=1", "name": "The East Arcade, other sheet", "text": "On this sheet, someone has crossed out the 1 and written −1."}], "doors": [{"to": 32, "wall": "right"}, {"to": 30, "wall": "left"}], "objects": [{"kind": "ref", "icon": "book", "title": "Visual Complex Analysis", "by": "Tristan Needham", "note": "Chapter 2 walks around branch points with pictures."}]}, {"id": 32, "closed": "renovation", "name": "The South Arcade", "wing": "branch", "floor": "checker", "decor": ["pillar", "lamp"], "at": [10, 3], "text": "The third side. Half a page is pinned to the pillar.", "phases": [{"when": "sheet:sqrt=1", "name": "The South Arcade, other sheet", "text": "On this sheet, the other half of the page is pinned where the first half was."}], "doors": [{"to": 33, "wall": "right"}, {"to": 31, "wall": "left"}], "objects": [{"kind": "key", "item": "page-left", "icon": "note", "title": "The left half of a torn page", "when": "sheet:sqrt=0"}, {"kind": "key", "item": "page-right", "icon": "note", "title": "The right half of a torn page", "when": "sheet:sqrt=1"}]}, {"id": 33, "closed": "renovation", "name": "The West Arcade", "wing": "branch", "floor": "checker", "decor": ["pillar", "lamp"], "at": [9, 3], "text": "The last side of the pillar, and the way out to the perspective corridor. The step from here to the North Arcade crosses the cut.", "phases": [{"when": "sheet:sqrt=1", "name": "The West Arcade, other sheet", "text": "You are on the other sheet. The way out is the same, but you may come back to a different house."}], "doors": [{"to": 30, "wall": "right", "lift": {"sqrt": 1}, "title": "across the cut"}, {"to": 32, "wall": "left"}, {"to": 5, "wall": "front", "title": "the perspective corridor"}]}, {"id": 35, "name": "The Office", "wing": "foyer", "hours": true, "floor": "planks", "decor": ["window", "lamp", "wainscot", "officefit"], "at": [4, 7], "text": "A working office, for now a sketch of the real one, which will be modeled here later: its desk, its shelves, its whiteboard, its view. The hours are posted on the wall, and the plate on the door outside says whether it's open.", "doors": [{"to": 0, "wall": "back", "title": "back to the Entry"}], "objects": [{"kind": "device", "icon": "linkbook", "mount": "pedestal", "wall": "left", "title": "A linking book: the Archive", "action": "link", "to": 22, "note": "A small book on a stand. Its panel shows the archive, moving faintly. Touch it to go there."}, {"kind": "device", "mount": "board", "wall": "back", "icon": "clock", "title": "Office hours", "action": "officehours", "info": "When the office is open, and where. The plate on the door outside says the same."}, {"kind": "unwritten", "icon": "lectern", "wall": "left", "title": "The real office, measured", "note": "A model of the actual office: the desk, the shelves, the whiteboard, the window."}, {"kind": "device", "icon": "note", "wall": "left", "title": "The calendar", "action": "notices", "info": "The month on a card: events, the problem of the week, and the news of the house."}, {"kind": "device", "icon": "numerary", "mount": "pedestal", "wall": "right", "title": "The numerary", "action": "numerals", "note": "A number in every way it has been written: cuneiform, khipu, Kaktovik, Cistercian, counting rods, and the rest."}]}, {"id": 36, "closed": "renovation", "name": "The Knot Garden", "wing": "garden", "floor": "gravel", "ceiling": "open", "decor": ["hedges", "knot"], "at": [5, 9], "text": "Past the sundial the paving gives way to gravel, and the walls to clipped box. In the middle is a knot garden, and this one is a knot in earnest: a single hedge that closes on itself, rising over and dipping under at each crossing. It's a trefoil, the simplest knot that can't be untied.\nGardeners have laid out knots since the Tudors. Topologists have argued about them since Tait, who tabulated them in the 1870s because Kelvin thought atoms might be knotted vortices in the ether. The atoms weren't, but the table survived.", "doors": [{"to": 34, "wall": "back", "title": "the sundial court"}, {"to": 37, "wall": "left", "title": "the hedge maze"}, {"to": 39, "wall": "right", "title": "the moon garden"}, {"to": 38, "wall": "front", "title": "the sunflower bed"}], "objects": [{"kind": "device", "icon": "tree", "wall": "left", "title": "The trefoil, drawn", "note": "Three crossings, and no way to fewer: the crossing number of the trefoil is 3. It is chiral, too. Its mirror image is a different knot, which you can check by walking around the hedge in a mirrored frame."}, {"kind": "unwritten", "icon": "cross", "wall": "left", "title": "A table of knots, to be planted", "note": "The figure-eight, the cinquefoil, and the rest of Tait's table up to seven crossings, each a bed of its own."}, {"kind": "unwritten", "icon": "scroll", "wall": "right", "title": "Knots for tying", "note": "The bowline, the clove hitch, the sheet bend: the practical knots, with the mathematics of each. A rope's knot is an open curve; tie its ends together and it becomes a knot in the topologist's sense."}], "marginalia": ["A knot is a closed curve in space, up to wiggling without cutting. The hedge rises and dips so the crossings are honest: over and under, not just touching.", "Tait, Kirkman, and Little tabulated knots by hand through the 1890s. The Perko pair, two entries in that table that are really the same knot, wasn't caught until 1974."], "bib": ["Colin Adams, <i>The Knot Book</i>, 1994.", "Peter Guthrie Tait, “On Knots,” <i>Transactions of the Royal Society of Edinburgh</i>, 1877.", "Clifford Ashley, <i>The Ashley Book of Knots</i>, 1944."]}, {"id": 37, "closed": "renovation", "name": "The Hedge Maze", "wing": "garden", "floor": "gravel", "ceiling": "open", "decor": ["hedges", "maze"], "at": [4, 9], "text": "Hedges higher than your head, and turnings that all look alike. The maze has a habit: some turnings carry you round a quarter turn, and some turn you inside out, so left and right trade places. The heart of the maze lets in only those who arrive mirrored.", "doors": [{"to": 36, "wall": "right", "title": "back to the knot garden"}, {"to": 37, "wall": "front", "turn": "r", "title": "a turning in the hedge", "say": "The path bends round. It looks like the same place, turned."}, {"to": 37, "wall": "left", "turn": "s", "title": "a turning that doubles back", "say": "The path doubles back on itself, and the hedges seem to have swapped sides."}, {"to": 41, "wall": "back", "needs": "mirror", "hint": "The hedge here only parts for someone who has been turned inside out.", "title": "a gap in the hedge"}], "objects": [{"kind": "book", "icon": "book", "wall": "right", "title": "Maze", "by": "Christopher Manson, 1985", "note": "Forty-five numbered rooms, a shortest path of sixteen steps, and a riddle along it. The house's numbered rooms are a homage."}], "marginalia": ["The turnings are holonomy you can walk: each door applies an element of the dihedral group to your frame. The heart needs the reflection, which no number of quarter turns will give you."], "bib": ["Christopher Manson, <i>Maze: Solve the World's Most Challenging Puzzle</i>, 1985.", "Jorge Luis Borges, “The Garden of Forking Paths,” 1941."]}, {"id": 41, "closed": "renovation", "name": "The Heart of the Maze", "wing": "garden", "floor": "lawn", "ceiling": "open", "decor": ["hedges", "fountain"], "at": [4, 10], "secret": true, "text": "A small square of lawn with a fountain, and a stone bench. You came in mirrored, and you'll leave mirrored unless you find another turning, or use the compass.\nMost mazes are trees, and a hand on one wall will get you out. This one isn't: its turnings are a group, and the way out depends on how you've been turned.", "doors": [{"to": 37, "wall": "front", "title": "back into the maze"}], "objects": [{"kind": "book", "icon": "book", "wall": "left", "title": "The Garden of Forking Paths", "by": "Jorge Luis Borges, 1941", "note": "A labyrinth in time, not space: a novel in which every choice is taken, and all the futures happen."}, {"kind": "unwritten", "icon": "hex", "wall": "left", "title": "A labyrinth, to be laid in the turf", "note": "The seven-circuit classical labyrinth: one path, no choices, all the way to the center."}], "marginalia": ["The hand-on-the-wall rule works exactly when the maze's walls are connected, a tree, as graph theorists say. A loop of hedge you can't reach from the outer wall defeats it."]}, {"id": 38, "closed": "renovation", "name": "The Sunflower Bed", "wing": "garden", "floor": "gravel", "ceiling": "open", "decor": ["hedges", "phyllo", "sunflowers"], "at": [5, 10], "text": "A round bed laid out seed by seed in Vogel's spiral: the n-th seed at distance √n from the center and n times the golden angle around. Count the spirals and you get Fibonacci numbers, 13, 21, and 34 here, because the golden angle is as far as an angle can get from any fraction.\nAround the edge, sunflowers. By day they turn to face the sun, wherever it really is; by night they face east, where it will rise.", "doors": [{"to": 36, "wall": "back", "title": "the knot garden"}, {"to": 40, "wall": "right", "title": "the orrery lawn"}], "objects": [{"kind": "device", "icon": "crystal", "wall": "back", "title": "The golden angle", "note": "360° × (1 − 1/φ) ≈ 137.508°. Its continued fraction is all ones, so it is the worst approximable number: no seed ever falls exactly behind another."}, {"kind": "unwritten", "icon": "plant", "wall": "back", "title": "Turing's sunflowers", "note": "Turing's last work was on phyllotaxis. In 2012 a citizen-science project grew hundreds of sunflowers to test it; most, though not all, counted Fibonacci."}], "marginalia": ["Vogel's model, 1979: r = c√n, θ = n · 137.508°. The square root keeps the seeds evenly packed; the golden angle keeps them from lining up."], "bib": ["Helmut Vogel, “A better way to construct the sunflower head,” <i>Mathematical Biosciences</i>, 1979.", "Jonathan Swinton and others, “Novel Fibonacci and non-Fibonacci structure in the sunflower,” <i>Royal Society Open Science</i>, 2016."]}, {"id": 39, "closed": "renovation", "name": "The Moon Garden", "wing": "garden", "floor": "gravel", "ceiling": "open", "decor": ["hedges", "moonflowers", "armillary"], "at": [6, 9], "widget": "sundial", "text": "Pale flowers in clipped bushes: moonflowers, evening primrose, nicotiana. By day they're shut. At dusk they open, and they glow a little under the moon.\nIn the middle stands an armillary sphere set up as an equatorial dial. Its rod points at the celestial pole, and its band lies in the plane of the equator, so its hours are evenly spaced, fifteen degrees each. The rod's shadow on the band is the sun's own time, read straight off the brass.", "doors": [{"to": 36, "wall": "left", "title": "the knot garden"}, {"to": 40, "wall": "front", "title": "the orrery lawn"}], "objects": [{"kind": "unwritten", "icon": "clock", "wall": "left", "title": "A moon dial's volvelle", "note": "A rotating disc that converts moon time to sun time by the moon's age. For now the dials here tell it as they see it."}], "marginalia": ["An equatorial dial is the easy one: tilt the dial plate until it's parallel to the equator, and the hour lines are evenly spaced. The horizontal dial in the court is the same dial, projected onto the ground."], "bib": ["Albert E. Waugh, <i>Sundials: Their Theory and Construction</i>, 1973."]}, {"id": 40, "closed": "renovation", "name": "The Orrery Lawn", "wing": "garden", "floor": "lawn", "ceiling": "open", "decor": ["hedges", "orrery"], "at": [6, 10], "text": "A brass orrery on a stone pedestal in the middle of the lawn, with the planets where they really are today, from Mercury out to Neptune. The distances are squeezed so Neptune fits; the angles are true. At night the real planets are overhead, and you can check one against the other.", "doors": [{"to": 39, "wall": "back", "title": "the moon garden"}, {"to": 38, "wall": "left", "title": "the sunflower bed"}], "objects": [{"kind": "device", "icon": "orrery", "wall": "left", "title": "The ephemeris", "action": "planets", "note": "Every planet tracked: where it is now, when it rises and sets, how bright it is, how far, and in which constellation."}, {"kind": "unwritten", "icon": "scroll", "wall": "left", "title": "A planet walk, to scale", "note": "The solar system on a scale where the sun is a beach ball: Neptune would be about two miles off, a long way past the edge of the lawn."}], "marginalia": ["The positions come from JPL's Keplerian elements for the planets, good to a few hundredths of a degree for 1800–2050.", "The first orrery of the modern kind was made around 1712 by George Graham and Thomas Tompion, and copied for Charles Boyle, the fourth Earl of Orrery, who gave it his name."], "bib": ["E. M. Standish, “Keplerian Elements for Approximate Positions of the Major Planets,” JPL.", "Jean Meeus, <i>Astronomical Algorithms</i>, 1991."]}, {"id": 42, "closed": "renovation", "name": "The Great Hall", "wing": "hall", "floor": "slate", "ceiling": "gothic", "size": 42, "length": 56, "height": 16, "gallery": 8, "walkway": 5, "core": [12, 16], "walk": true, "level": 0, "see": 64, "at": [6, 6], "text": "A stone hall four storeys high and more than fifty meters long, built round the footing of a tower. Down the middle stands the core, with the elevators behind tall wrought-iron gates, front and back, and a line of verse cut over each gate. Beside it a stone turret winds its stair up to the third floor. Round the core runs a ring of vaulted bays, ribbed and bossed in gilt, with lanterns on long chains, long oak tables, and a floor of green slate. At the far end is an enormous fireplace.\nTwo storeys up, a walkway runs all the way round the walls behind a pierced stone parapet, with two bridges across to the core. Rooms open off the walkway, and off the floor beneath it. All of them are boarded up for now: they are for later.\nMove from place to place on the slate: click the floor where you want to go, or use W and S; A and D turn you. The turret stair and the elevators behind the gates take you up to the walkway, down to the undercroft, or up the tower. The Lamps button turns the lanterns down for the hall as it really is, which is dark, or lights them all. The Entry is behind you.", "again": "The fire is still burning. Somewhere up on the walkway a door closes.", "marginalia": ["A homage to the Commons Room of the University of Pittsburgh's Cathedral of Learning: a fifteenth-century English Perpendicular Gothic hall, four storeys and about 52 feet (16 m) high, covering about half an acre, at the foot of the tower.", "The plan here is pieced together from what is written about the real room rather than from its drawings: it rings the tower's core, where the elevators are; its central piers are screens for the steel that carries the floors above; the Nationality Rooms ring it, 19 on the first floor and 12 on the third, from which you look down into the hall.", "The real arches are true arches: Indiana limestone, no steel. The vault ribs are lined with Guastavino acoustic tile to keep the room quiet.", "Samuel Yellin made the real wrought-iron gates, eighteen feet tall, between the Commons Room and the elevator bank, with the line from Robert Bridges cut over the gates here.", "Joseph Gattoni designed the real stonework, carving the plants of western Pennsylvania into it. The leaves on these capitals are a nod to his.", "There is a stone-lined circular stair into the real Commons Room that, as one alumnus remembered, feels like a castle turret, and an enormous fireplace that heats the room in winter. People who studied there remember it as dark."], "sources": ["The Commons Room of the Cathedral of Learning, University of Pittsburgh (Charles Klauder, architect; completed in the 1930s)."], "bib": ["“Cathedral of Learning” and “Nationality Rooms,” Wikipedia.", "University of Pittsburgh, “Cathedral Commons Room,” tour.pitt.edu; “Commons Room Gates,” art.pitt.edu.", "John Fredette, “Cathedral Memories,” cathedral100.pitt.edu."], "doors": [{"to": 43, "wall": "left", "title": "the first room off the floor"}, {"to": 44, "wall": "left", "title": "the second room off the floor"}, {"to": 45, "wall": "left", "title": "the third room off the floor"}, {"to": 46, "wall": "left", "title": "the fourth room off the floor"}, {"to": 47, "wall": "right", "title": "the fifth room off the floor"}, {"to": 48, "wall": "right", "title": "the sixth room off the floor"}, {"to": 49, "wall": "right", "title": "the seventh room off the floor"}, {"to": 50, "wall": "right", "title": "the eighth room off the floor"}, {"to": 66, "wall": "back", "fixture": "lift-front", "car": 1, "title": "the elevators"}, {"to": 66, "wall": "back", "fixture": "lift-back", "car": 1, "title": "the elevators"}, {"to": 65, "wall": "back", "fixture": "turret", "landing": 1, "title": "the turret stair"}, {"to": 0, "wall": "front", "title": "back to the Entry"}]}, {"id": 64, "closed": "renovation", "name": "The Walkway", "wing": "hall", "floor": "slate", "ceiling": "gothic", "size": 42, "length": 56, "height": 16, "gallery": 8, "walkway": 5, "core": [12, 16], "walk": true, "level": 1, "see": 42, "at": [7, 5], "text": "The third-floor walkway of the Great Hall: a stone deck all the way round, behind a pierced parapet, looking down into the hall. Two bridges cross to a balcony round the core. Rooms open off the walkway, all boarded up for now.\nMove from place to place along the walkway, over the bridges, and round the balcony: click where you want to go, or use W and S. The elevators and the turret stair are on the balcony.", "again": "Below you the lanterns burn over the long tables.", "doors": [{"to": 51, "wall": "left", "level": 1, "title": "a room off the walkway"}, {"to": 52, "wall": "left", "level": 1, "title": "a room off the walkway"}, {"to": 53, "wall": "left", "level": 1, "title": "a room off the walkway"}, {"to": 54, "wall": "left", "level": 1, "title": "a room off the walkway"}, {"to": 55, "wall": "left", "level": 1, "title": "a room off the walkway"}, {"to": 56, "wall": "left", "level": 1, "title": "a room off the walkway"}, {"to": 57, "wall": "right", "level": 1, "title": "a room off the walkway"}, {"to": 58, "wall": "right", "level": 1, "title": "a room off the walkway"}, {"to": 59, "wall": "right", "level": 1, "title": "a room off the walkway"}, {"to": 60, "wall": "right", "level": 1, "title": "a room off the walkway"}, {"to": 61, "wall": "right", "level": 1, "title": "a room off the walkway"}, {"to": 62, "wall": "right", "level": 1, "title": "a room off the walkway"}, {"to": 66, "wall": "back", "fixture": "lift-front", "car": 2, "title": "the elevators"}, {"to": 65, "wall": "back", "fixture": "turret-up", "landing": 2, "title": "the turret stair"}]}, {"id": 65, "closed": "renovation", "name": "The Turret Stair", "wing": "hall", "at": [7, 7], "landings": [{"y": -4.4, "name": "the undercroft"}, {"y": 0, "name": "the floor of the Great Hall"}, {"y": 8, "name": "the third-floor walkway"}, {"y": 12.4, "name": "the fourth floor"}], "start": 1, "text": "A stone-lined stair winding up inside its turret, like a castle's: a landing at every floor, each with its door and a lamp by it, and slit windows on the way. Press W or S, or click the stair going up or down, and you climb or descend to the next landing.", "doors": [{"to": 71, "wall": "back", "stop": 0, "title": "the undercroft"}, {"to": 42, "wall": "back", "stop": 1, "title": "out to the floor of the Great Hall"}, {"to": 64, "wall": "back", "stop": 2, "title": "out to the walkway"}, {"to": 72, "wall": "back", "stop": 3, "title": "the fourth floor"}]}, {"id": 66, "closed": "renovation", "name": "The Elevator", "wing": "hall", "at": [8, 7], "floors": [{"n": "B", "name": "The undercroft", "closed": true}, {"n": "1", "name": "The Great Hall"}, {"n": "3", "name": "The walkway"}, {"n": "36", "name": "The Overlook"}], "start": 1, "text": "A walnut-and-bronze car behind a folding gate, with a dial over the gate and a button for every floor it serves. Press a button and the gate folds shut, the needle swings, and the car carries you there. When the gate opens, step out through the door ahead.", "doors": [{"to": 71, "wall": "back", "stop": 0, "title": "the undercroft"}, {"to": 42, "wall": "back", "stop": 1, "title": "out to the Great Hall"}, {"to": 64, "wall": "back", "stop": 2, "title": "out to the walkway"}, {"to": 67, "wall": "back", "stop": 3, "title": "out to the Overlook"}]}, {"id": 67, "closed": "renovation", "name": "The Overlook", "wing": "tower", "floor": "planks", "ceiling": "coffers", "size": 18, "height": 5.6, "windows": "all", "winH": 3.8, "winW": 1.8, "decor": ["panorama", "lounge", "rug"], "at": [13, 1], "text": "The top of the tower: a quiet room with tall windows on every side and the whole land laid out below, in the light of the hour. Armchairs stand round a low table, with lamps for reading. (In the real Cathedral of Learning the top floors hold the Honors College, with its view over Pittsburgh.)\nA stair goes on up to the roof and the observatory. On the left are the map room and a closed door; on the right, the weather station and another. The elevator is behind you.", "again": "The light has moved across the floor since you were last here.", "doors": [{"to": 66, "wall": "front", "car": 3, "title": "the elevator"}, {"to": 68, "wall": "back", "title": "up the stair to the roof"}, {"to": 69, "wall": "left", "title": "the map room"}, {"to": 73, "wall": "left", "title": "a closed room"}, {"to": 70, "wall": "right", "title": "the weather station"}, {"to": 74, "wall": "right", "title": "a closed room"}]}, {"id": 68, "closed": "renovation", "name": "The Roof and the Observatory", "wing": "tower", "floor": "stone", "ceiling": "open", "size": 24, "height": 3.3, "windows": "all", "winSill": 1.0, "winH": 1.9, "winW": 2.6, "decor": ["panorama", "observatory"], "at": [13, 0], "text": "The roof of the tower, open to the sky, with an arcade of stone all round and the land far below. In the middle stands a little observatory: a round stone house under a copper dome with its slit open, and inside it a long brass refractor on an iron pier, aimed at the sky.\nClick the telescope to look through it: the Moon in its real phase, the planets that are up tonight, Jupiter with its four great moons where they really are, Saturn with its rings at their true tilt, and some of the sky's showpieces. The sky overhead is the real one; click it to go up into it.", "again": "The dome's slit is still open. The telescope hasn't moved.", "doors": [{"to": 67, "wall": "front", "title": "down the stair to the Overlook"}], "objects": [{"kind": "device", "icon": "orrery", "wall": "back", "title": "The observing log", "action": "telescope", "note": "What's up tonight, and a look at it through the telescope."}]}, {"id": 69, "closed": "renovation", "name": "The Map Room", "wing": "tower", "floor": "planks", "ceiling": "coffers", "size": 10, "height": 4.6, "windows": "all", "winH": 2.8, "decor": ["panorama", "maptable"], "at": [14, 1], "text": "A long table with the map of the land below spread on it, from OpenStreetMap, and the same land out of every window. Click the table to look closer, zoom in or out, and match the map to the view.", "doors": [{"to": 67, "wall": "front", "title": "back to the Overlook"}]}, {"id": 70, "closed": "renovation", "name": "The Weather Station", "wing": "tower", "floor": "planks", "ceiling": "coffers", "size": 10, "height": 4.6, "windows": "all", "winH": 2.8, "decor": ["panorama", "wxstation"], "at": [12, 1], "text": "The house's instruments, reading the real weather at the top of the tower: a barometer, a hygrometer, an anemometer and rain dial, the wind vane's repeater, a thermometer, a rain gauge, and a barograph turning on its drum. Click the instruments to read the week's record.", "doors": [{"to": 67, "wall": "front", "title": "back to the Overlook"}]}, {"id": 71, "closed": "renovation", "name": "The Undercroft", "wing": "tower", "at": [13, 9], "text": "Beneath the Great Hall, at the foot of the turret stair. Closed for now.", "doors": [{"to": 67, "wall": "front", "title": "back"}]}, {"id": 72, "closed": "renovation", "name": "The Fourth Floor", "wing": "tower", "at": [13, 8], "text": "Above the walkway, off the turret stair. Closed for now.", "doors": [{"to": 67, "wall": "front", "title": "back"}]}, {"id": 73, "closed": "renovation", "name": "A Room at the Top", "wing": "tower", "at": [14, 0], "text": "Off the Overlook. Closed for now.", "doors": [{"to": 67, "wall": "front", "title": "back"}]}, {"id": 74, "closed": "renovation", "name": "Another Room at the Top", "wing": "tower", "at": [12, 0], "text": "Off the Overlook. Closed for now.", "doors": [{"to": 67, "wall": "front", "title": "back"}]}, {"id": 43, "closed": "renovation", "name": "The First Alcove", "wing": "hall", "floor": "slate", "ceiling": "vault", "at": [11, 2], "text": "A room off the floor of the Great Hall, on the left as you come in. Empty for now: it is waiting for its fittings.", "doors": [{"to": 42, "wall": "front", "title": "back to the Great Hall"}]}, {"id": 44, "closed": "renovation", "name": "The Second Alcove", "wing": "hall", "floor": "slate", "ceiling": "vault", "at": [11, 3], "text": "A room off the floor of the Great Hall, on the left as you come in. Empty for now: it is waiting for its fittings.", "doors": [{"to": 42, "wall": "front", "title": "back to the Great Hall"}]}, {"id": 45, "closed": "renovation", "name": "The Third Alcove", "wing": "hall", "floor": "slate", "ceiling": "vault", "at": [11, 4], "text": "A room off the floor of the Great Hall, on the left as you come in. Empty for now: it is waiting for its fittings.", "doors": [{"to": 42, "wall": "front", "title": "back to the Great Hall"}]}, {"id": 46, "closed": "renovation", "name": "The Fourth Alcove", "wing": "hall", "floor": "slate", "ceiling": "vault", "at": [11, 5], "text": "A room off the floor of the Great Hall, on the left as you come in. Empty for now: it is waiting for its fittings.", "doors": [{"to": 42, "wall": "front", "title": "back to the Great Hall"}]}, {"id": 47, "closed": "renovation", "name": "The Fifth Alcove", "wing": "hall", "floor": "slate", "ceiling": "vault", "at": [11, 6], "text": "A room off the floor of the Great Hall, on the right as you come in. Empty for now: it is waiting for its fittings.", "doors": [{"to": 42, "wall": "front", "title": "back to the Great Hall"}]}, {"id": 48, "closed": "renovation", "name": "The Sixth Alcove", "wing": "hall", "floor": "slate", "ceiling": "vault", "at": [11, 7], "text": "A room off the floor of the Great Hall, on the right as you come in. Empty for now: it is waiting for its fittings.", "doors": [{"to": 42, "wall": "front", "title": "back to the Great Hall"}]}, {"id": 49, "closed": "renovation", "name": "The Seventh Alcove", "wing": "hall", "floor": "slate", "ceiling": "vault", "at": [11, 8], "text": "A room off the floor of the Great Hall, on the right as you come in. Empty for now: it is waiting for its fittings.", "doors": [{"to": 42, "wall": "front", "title": "back to the Great Hall"}]}, {"id": 50, "closed": "renovation", "name": "The Eighth Alcove", "wing": "hall", "floor": "slate", "ceiling": "vault", "at": [11, 9], "text": "A room off the floor of the Great Hall, on the right as you come in. Empty for now: it is waiting for its fittings.", "doors": [{"to": 42, "wall": "front", "title": "back to the Great Hall"}]}, {"id": 51, "closed": "renovation", "name": "Gallery Room 1", "wing": "hall", "floor": "planks", "at": [12, 0], "text": "A room off the third-floor walkway of the Great Hall, on the left. Empty for now: it is waiting for its fittings.", "doors": [{"to": 64, "wall": "front", "title": "out to the walkway"}]}, {"id": 52, "closed": "renovation", "name": "Gallery Room 2", "wing": "hall", "floor": "planks", "at": [12, 1], "text": "A room off the third-floor walkway of the Great Hall, on the left. Empty for now: it is waiting for its fittings.", "doors": [{"to": 64, "wall": "front", "title": "out to the walkway"}]}, {"id": 53, "closed": "renovation", "name": "Gallery Room 3", "wing": "hall", "floor": "planks", "at": [12, 2], "text": "A room off the third-floor walkway of the Great Hall, on the left. Empty for now: it is waiting for its fittings.", "doors": [{"to": 64, "wall": "front", "title": "out to the walkway"}]}, {"id": 54, "closed": "renovation", "name": "Gallery Room 4", "wing": "hall", "floor": "planks", "at": [12, 3], "text": "A room off the third-floor walkway of the Great Hall, on the left. Empty for now: it is waiting for its fittings.", "doors": [{"to": 64, "wall": "front", "title": "out to the walkway"}]}, {"id": 55, "closed": "renovation", "name": "Gallery Room 5", "wing": "hall", "floor": "planks", "at": [12, 4], "text": "A room off the third-floor walkway of the Great Hall, on the left. Empty for now: it is waiting for its fittings.", "doors": [{"to": 64, "wall": "front", "title": "out to the walkway"}]}, {"id": 56, "closed": "renovation", "name": "Gallery Room 6", "wing": "hall", "floor": "planks", "at": [12, 5], "text": "A room off the third-floor walkway of the Great Hall, on the left. Empty for now: it is waiting for its fittings.", "doors": [{"to": 64, "wall": "front", "title": "out to the walkway"}]}, {"id": 57, "closed": "renovation", "name": "Gallery Room 7", "wing": "hall", "floor": "planks", "at": [12, 6], "text": "A room off the third-floor walkway of the Great Hall, on the right. Empty for now: it is waiting for its fittings.", "doors": [{"to": 64, "wall": "front", "title": "out to the walkway"}]}, {"id": 58, "closed": "renovation", "name": "Gallery Room 8", "wing": "hall", "floor": "planks", "at": [12, 7], "text": "A room off the third-floor walkway of the Great Hall, on the right. Empty for now: it is waiting for its fittings.", "doors": [{"to": 64, "wall": "front", "title": "out to the walkway"}]}, {"id": 59, "closed": "renovation", "name": "Gallery Room 9", "wing": "hall", "floor": "planks", "at": [12, 8], "text": "A room off the third-floor walkway of the Great Hall, on the right. Empty for now: it is waiting for its fittings.", "doors": [{"to": 64, "wall": "front", "title": "out to the walkway"}]}, {"id": 60, "closed": "renovation", "name": "Gallery Room 10", "wing": "hall", "floor": "planks", "at": [12, 9], "text": "A room off the third-floor walkway of the Great Hall, on the right. Empty for now: it is waiting for its fittings.", "doors": [{"to": 64, "wall": "front", "title": "out to the walkway"}]}, {"id": 61, "closed": "renovation", "name": "Gallery Room 11", "wing": "hall", "floor": "planks", "at": [12, 10], "text": "A room off the third-floor walkway of the Great Hall, on the right. Empty for now: it is waiting for its fittings.", "doors": [{"to": 64, "wall": "front", "title": "out to the walkway"}]}, {"id": 62, "closed": "renovation", "name": "Gallery Room 12", "wing": "hall", "floor": "planks", "at": [12, 11], "text": "A room off the third-floor walkway of the Great Hall, on the right. Empty for now: it is waiting for its fittings.", "doors": [{"to": 64, "wall": "front", "title": "out to the walkway"}]}], "primer": {"2": {"teaser": "every rule is an exponential map you can hold", "lesson": "A slide rule adds lengths, and the scale is logarithmic, so adding lengths multiplies numbers.", "q": "Why can't a slide rule add 2 + 3?", "a": "Its scale turns addition of lengths into multiplication of numbers. To add you'd need a plain ruler, whose scale is the identity."}, "3": {"teaser": "a wheel measures area by walking around it", "lesson": "A planimeter traces the edge of a shape and reads off the area inside, which is Green's theorem in brass.", "q": "If you trace the boundary backwards, what happens?", "a": "You get the same area with a minus sign. The orientation of the loop matters."}, "7": {"teaser": "a pendulum turns although nothing turns it", "lesson": "The swing of the pendulum keeps its direction while the earth turns under it. In Appleton it comes round once every 34 hours or so.", "q": "Where on earth does the pendulum turn once a day?", "a": "At the poles, where sin φ = 1. At the equator it doesn't turn at all."}, "8": {"teaser": "two turns add like arrows on a sphere", "lesson": "Rotations don't commute. Turn a book a quarter turn forward and then a quarter turn left; then do it in the other order.", "q": "Which group do the eight symmetries of a square form?", "a": "The dihedral group D₄. It's the frame the house carries you in."}, "10": {"teaser": "a lock only opens for symmetries", "lesson": "The roots of x⁴ − 2 can be shuffled only in ways that keep every rational relation true.", "q": "How many ways are there?", "a": "Eight, the symmetries of a square, out of 24 shuffles."}, "11": {"teaser": "half the arrangements can never be reached", "lesson": "Every slide of the fifteen puzzle changes the permutation's sign and moves the blank one step; together, nothing changes.", "q": "Can you swap just the 14 and 15?", "a": "No. That would change the invariant."}, "15": {"teaser": "a man remembered everything and could add nothing", "lesson": "Funes gave every number its own name. Without place value, names can be memorized but not computed with.", "q": "What does the 6 in 365 mean?", "a": "Six tens. Funes's system has no way to say that."}, "16": {"teaser": "the slowest gcd is made of Fibonacci numbers", "lesson": "Euclid's algorithm cuts off squares. Fibonacci rectangles cut off one square at a time, so they take the longest.", "q": "How many steps for gcd(89, 55)?", "a": "Nine. The numbers fall back through the Fibonacci sequence: 89, 55, 34, 21, 13, 8, 5, 3, 2, 1."}, "4": {"teaser": "the ceiling is tonight's real sky", "lesson": "The dome uses stereographic projection, which sends circles to circles. The horizon is the edge of the dome.", "q": "Which star stays put at the top of the sky's turning?", "a": "Polaris, very nearly. It sits about 44° up in Appleton, which is the latitude."}, "27": {"teaser": "every islander either always lies or never does", "lesson": "When a knave describes what a knight would say, the answer you hear is false either way.", "q": "If you ask any islander 'Are you a knight?', what do they say?", "a": "Yes, every time. So the question tells you nothing."}}};
